/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"보관의 기능","줄":[{"t":"보관은 시간적 효용을 창출한다. 생산과 소비의 시간 간격을 메운다.","src":"기출 2021-1, 2022-2, 2023-12"},{"t":"장소적 효용은 운송이 창출한다. 보관의 기능이 아니다.","src":"기출 2021-1, 2023-1, 2025-4"},{"t":"수송과 배송을 연계한다.","src":"기출 2021-1, 2022-2, 2023-1, 2026-1"},{"t":"생산과 판매를 조정하고 완충한다(생산 평준화·안정화 지원).","src":"기출 2021-1, 2022-2, 2026-1"},{"t":"재고를 보유해 고객 수요에 대응한다. 고객 서비스에 신속히 대응한다.","src":"기출 2021-1, 2022-2, 2023-1, 2025-4"},{"t":"물품의 분류와 혼재, 보존과 관리도 보관 기능에 든다.","src":"기출 2023-1"},{"t":"유통가공·재포장·검품도 보관(창고) 기능에 포함된다.","src":"기출 2026-1, 2024-15"},{"t":"물품의 수급 조정 기능이 있다.","src":"기출 2025-4"}]},{"머리":"보관의 원칙 전체","줄":[{"t":"위치표시의 원칙: 보관 물품의 장소와 선반 번호를 표시해 입출고·재고 작업 효율을 높인다.","src":"기출 2021-3, 2022-1, 2024-1"},{"t":"회전대응의 원칙: 입출고 빈도가 높은 물품은 출입구 가까이, 낮은 물품은 먼 곳에 둔다.","src":"기출 2021-3, 2022-1, 2023-4, 2025-1"},{"t":"선입선출의 원칙: 먼저 입고한 물품을 먼저 출고한다.","src":"기출 2022-1, 2025-1, 2026-2"},{"t":"중량특성의 원칙: 중량에 따라 보관 위치(높이)를 정한다. 무거운 물품은 하층부에 둔다.","src":"기출 2022-1, 2024-1, 2025-1, 2026-2"},{"t":"동일성·유사성의 원칙: 동일 품종은 같은 장소에, 유사품은 인접 장소에 둔다. 관리 효율이 오른다.","src":"기출 2024-1, 2025-1, 2026-2"},{"t":"통로대면의 원칙: 입출고를 쉽게 하려고 물품을 통로에 접하게 보관한다.","src":"기출 2024-1, 2026-2"},{"t":"네트워크 보관의 원칙: 연대출고가 예상되는 관련 품목을 출하하기 쉽게 모아 계통적으로 보관한다.","src":"기출 2021-3, 2022-1"},{"t":"명료성의 원칙: 보관 물품을 눈으로 쉽게 식별할 수 있게 둔다.","src":"보충(추정)"},{"t":"형상특성의 원칙: 물품의 형상에 맞추어 보관한다.","src":"기출 2021-3 / 보충"}]},{"머리":"보관유형(품목수·수량·회전율)","줄":[{"t":"A-A-A형: 품목수 적음, 수량 많음, 회전율 높음.","src":"기출 2024-2"},{"t":"C-A-A형: 품목수와 수량이 매우 많고 회전율이 높다. 관리가 복잡해 자동화 방식이 적합하다.","src":"기출 2024-2"}]}],"함정":[{"x":"유사성의 원칙: 연대출고가 예상되는 관련 품목을 출하가 용이하도록 모아서 보 관하는 원칙이다.","o":"연대출고가 예상되는 관련 품목을 출하하기 쉽게 모아 보관하는 원칙은 네트워크보관의 원칙이다. 유사성의 원칙은 유사품을 가까운 장소에 모아 보관한다.","src":"기출 2022-1 / 기출 2021-3, 2024-1"},{"x":"네트워크 보관의 원칙: 입출고 빈도에 따라 보관할 물품의 위치를 달리하는 원 칙으로 빈도가 높은 물품은 출입구 가까운 위치에 보관한다.","o":"입출고 빈도에 따라 보관 위치를 달리하는 원칙은 회전대응의 원칙이다.","src":"기출 2024-1 / 기출 2021-3, 2022-1, 2023-4"},{"x":"통로대면의 원칙: 작업의 효율성을 위하여 보관물품의 장소와 선반 번호 위치를 표시하여 보관한다.","o":"통로대면의 원칙: 입출고를 쉽게 하려고 물품을 통로에 접하게 보관한다. 장소·선반번호를 표시하는 것은 위치표시의 원칙이다.","src":"기출 2025-1 / 기출 2022-1, 2024-1, 2026-2"},{"x":"유통가공, 재포장, 검품은 보관의 기능으로 분류되지 않는다.","o":"유통가공·재포장·검품도 창고(보관)의 기능이다.","src":"기출 2026-1 / 기출 2024-15"},{"x":"명료성의 원칙: 용적 효율을 향상시키기 위해 물품을 높게 쌓는다.","o":"명료성의 원칙: 보관 물품을 눈으로 쉽게 식별할 수 있게 보관한다. 높게 쌓아 용적효율을 높인다는 설명은 아니다.","src":"기출 2026-2 / 보충(추정)"},{"x":"제품에 대한 장소적 효용을 창출한다.","o":"보관은 시간적 효용을 창출한다. 장소적 효용은 운송 기능이다.","src":"기출 2021-1"},{"x":"거리적·장소적 효용 창출 기능(보관의 기능으로)","o":"보관의 기능이 아니다. 장소적 효용은 운송이 창출한다.","src":"기출 2023-1"},{"x":"제품의 판매촉진을 위한 장소적 효용 창출 기능(보관의 기능으로)","o":"보관의 기능이 아니다.","src":"기출 2025-4"}]},"#2":{"묶음":[{"머리":"물류시설법의 정의","줄":[{"t":"물류터미널: 화물의 집화·하역 및 이와 관련된 분류·포장·보관·가공·조립 또는 통관 등에 필요한 기능을 갖춘 시설물이다. 가공·조립 시설은 대통령령 규모 이하여야 한다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2023-7, 2025-5, 2026-3"},{"t":"복합물류터미널사업: 두 종류 이상의 운송수단 간 연계운송을 할 수 있는 규모 및 시설을 갖춘 물류터미널사업이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2023-3, 2024-3, 2025-3"},{"t":"일반물류터미널사업: 물류터미널사업 중 복합물류터미널사업을 제외한 것이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"물류창고: 화물의 저장·관리, 집화·배송 및 수급조정 등을 위한 보관시설·보관장소, 또는 이와 관련된 하역·분류·포장·상표부착 등에 필요한 기능을 갖춘 시설이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"스마트물류센터: 첨단물류시설·설비·운영시스템을 도입해 저비용·고효율·안전성·친환경성 등이 우수한 물류창고로, 국토교통부장관의 인증을 받은 물류창고이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2024-4, 2026-5"},{"t":"물류단지: 도시첨단물류단지와 일반물류단지로 나눈다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"},{"t":"도시첨단물류단지: 도시 내 물류를 지원하고 물류·유통산업과 관련 산업의 육성·개발을 촉진하려고 도시지역에 지정·개발하는 단지이다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2024-4"},{"t":"일반물류단지시설에는 물류터미널 및 창고, 대규모점포·공동집배송센터·중소유통공동도매물류센터, 농수산물도매시장·공판장·종합유통센터, 화물자동차운수사업용 차고·화물취급소 등이 든다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조"}]},{"머리":"물류터미널·복합물류터미널·배송센터","줄":[{"t":"복합물류터미널: 복수 운송수단 간 연계 규모·시설, 화물취급장, 창고, 유통가공시설, 편의시설을 갖춘다. 환적과 화물정보센터 기능도 한다.","src":"기출 2023-3, 2024-3, 2025-3, 2026-3"},{"t":"복합물류터미널은 보관 위주 시설이 아니고 환적물량을 취급한다. 물류정보 기능도 포함한다.","src":"기출 2024-3, 2025-3"},{"t":"물류터미널의 기능: 집하·하역·분류·포장·보관·가공·조립·혼재·환적·재포장·화물정보 제공.","src":"기출 2021-6, 2022-5, 2023-7"},{"t":"물류센터의 기능: 조립·유통가공, 상품 보호를 위한 포장, 입출고를 위한 오더피킹.","src":"기출 2021-14"},{"t":"배송센터의 일반 기능: 보관, 분류, 배송, 수집, 유통가공. 통관은 하지 않는다.","src":"기출 2026-16"},{"t":"공동집배송센터: 여러 유통사업자·제조업자가 공동으로 쓰는 집배송시설과 부대업무시설을 갖춘다.","src":"기출 2023-7, 2025-5"},{"t":"스톡 포인트(Stock Point): 재고품의 임시보관 거점이자 배송거점이며 예상 수요에 대한 보관 장소이다. 대도시·지방 중소도시의 효율적 배송을 위한 유통 중계시설이다.","src":"기출 2023-3, 2025-5"},{"t":"공동집배송단지 도입 효과: 계획 배송으로 차량 적재효율 상승, 혼합배송으로 공차율 감소, 공동 참여로 대량 구매·계획 매입, 물류작업 공동화로 물류비 절감.","src":"기출 2023-2"},{"t":"공동집배송단지는 보관 수요를 통합 관리하므로 업체별 보관 공간과 관리 비용이 줄어든다.","src":"기출 2023-2"}]},{"머리":"입지·소유에 따른 물류센터 분류","줄":[{"t":"항만 입지형: 부두 창고, 임항 창고, 보세 창고 등이 있다.","src":"기출 2022-3"},{"t":"단지 입지형: 유통업무단지 등 유통 거점에 집중 입지한다. 공동창고, 집배송단지, 복합물류터미널 등이다.","src":"기출 2022-3"},{"t":"도시 근교 입지형: 백화점·슈퍼마켓·대형 할인매장·인터넷 쇼핑몰 등을 지원하는 창고이다.","src":"기출 2022-3"},{"t":"자가 시설: 제조·유통업체가 자기 책임으로 운영하는 물류센터이다.","src":"기출 2022-3"}]},{"머리":"컨테이너 관련 시설 (ICD·CY·CFS)","줄":[{"t":"ICD(Inland Container Depot): 수출입 통관, 집하·분류를 하고 트럭회사·포워더를 유치하므로 내륙 항만이라 부른다.","src":"기출 2021-5, 2024-4"},{"t":"ICD는 마샬링과 본선 선적·양하는 하지 않는다. 그것은 항만 컨테이너터미널의 기능이다.","src":"기출 2024-4"},{"t":"ICD 특성: 다양한 교통수단과의 높은 연계성이 입지조건이다. 통관이 빨라져 통관비가 줄어든다. 통관검사 후 재포장이 필요하면 ICD 자체 포장시설을 이용할 수 있다.","src":"기출 2022-4"},{"t":"ICD는 항만지역에 비해 창고용 토지 매입이 쉽고, 화물을 대단위화해 운송 효율을 높인다.","src":"기출 2022-4 / 보충(추정)"},{"t":"CY(Container Yard): 컨테이너를 인도·인수·보관하는 장소.","src":"기출 2024-4, 2025-6 / 보충"},{"t":"CFS(Container Freight Station): LCL 화물을 모아 목적지별로 선별해 컨테이너에 적입(Stuffing)하고, FCL 화물을 분리(Stripping)하는 시설이다.","src":"기출 2021-18, 2023-3, 2025-6"},{"t":"ODCY(Off Dock Container Yard): 부두 밖에 있는 컨테이너 장치장.","src":"기출 2026-3 / 보충"}]},{"머리":"보세구역 (관세법)","줄":[{"t":"보세구역은 지정보세구역·특허보세구역·종합보세구역으로 나눈다.","src":"관세법 제154조 / 기출 2025-7"},{"t":"지정보세구역은 지정장치장과 세관검사장으로 나눈다.","src":"관세법 제154조 / 기출 2023-7"},{"t":"특허보세구역은 보세창고·보세공장·보세전시장·보세건설장·보세판매장으로 나눈다. 세관검사장은 특허보세구역이 아니다.","src":"관세법 제154조 / 기출 2023-7, 2026-7"},{"t":"지정장치장은 통관을 하려는 물품을 일시 장치하기 위한 장소로 세관장이 지정하는 구역이다.","src":"관세법 제169조 / 기출 2025-7"},{"t":"세관장은 국가, 지방자치단체, 공항시설·항만시설을 관리하는 법인이 소유·관리하는 토지·건물 등을 지정보세구역으로 지정할 수 있다.","src":"관세법 제166조"},{"t":"특허보세구역을 설치·운영하려는 자는 세관장의 특허를 받아야 한다. 갱신도 같다.","src":"관세법 제174조 / 기출 2025-7"},{"t":"보세창고에는 외국물품이나 통관을 하려는 물품을 장치한다.","src":"관세법 제183조 / 기출 2023-13, 2025-12"},{"t":"보세공장에서는 외국물품을 원료 또는 재료로 하거나 외국물품과 내국물품을 원료로 하여 제조·가공 등을 할 수 있다. 내국물품만 원료로 하려면 세관장의 허가가 필요하다.","src":"관세법 제185조 / 기출 2025-7"},{"t":"종합보세구역에서는 보세창고·보세공장·보세전시장·보세건설장·보세판매장 기능 중 둘 이상을 수행할 수 있다. 지정권자는 관세청장이다.","src":"관세법 제197조 / 기출 2025-7"},{"t":"세관검사장: 통관을 위한 물품을 반입해 세관검사를 받게 하는 장소.","src":"기출 2025-7"}]},{"머리":"그 밖의 물류시설","줄":[{"t":"농수산물종합유통센터: 농수산물의 수집·포장·가공·보관·수송·판매 기능을 한다. 통관 기능은 없다.","src":"기출 2024-4"},{"t":"중소유통공동도매물류센터는 일반물류단지시설에 든다.","src":"물류시설의 개발 및 운영에 관한 법률 제2조 / 기출 2026-5"}]}],"함정":[{"x":"마샬링(Marshalling) 기능과 선박의 양하 작업을 수행한다.","o":"마샬링(Marshalling)과 선박의 양하 작업은 컨테이너터미널(항만)의 기능이다. 복합물류터미널·물류터미널이 하는 일이 아니다.","src":"기출 2021-6 / 보충"},{"x":"임대 시설은 화차로 출하하기 위하여 일시 대기하는 화물의 보관을 위한 물류센 터이다.","o":"임대 시설: 임차(리스)해서 쓰는 물류센터. 화차 출하 전 일시 대기 화물을 보관하는 센터는 철도역 연계형의 설명이다.","src":"기출 2022-3 / 보충(추정)"},{"x":"장기보관 위주의 보관 기능을 강화한 시설이다.","o":"물류터미널·복합물류터미널은 환적·혼재·재포장·정보 기능을 하며 장기보관 위주의 시설이 아니다.","src":"기출 2022-5 / 기출 2022-5, 2024-3"},{"x":"배송센터는 장치보관, 수출입 통관, 선박의 적하 및 양하기능을 수행하는 육상운송 수단과의 연계 지원시설이다.","o":"배송센터는 보관·분류·배송·수집·유통가공을 한다. 장치보관·통관·선박 적양하는 ICD·항만의 기능이다.","src":"기출 2023-7 / 기출 2021-5, 2026-16"},{"x":"보관기능 위주로 운영되는 물류시설로 환적물량은 취급하지 않는다.","o":"복합물류터미널은 환적물량을 취급한다. 보관 위주 시설이 아니다.","src":"기출 2024-3 / 기출 2024-3, 2025-3"},{"x":"ICD 설명을 도시첨단물류단지에 붙인 선지(2024-4 선지 5)","o":"수출입 통관·집하·분류, 트럭회사·포워더 유치, 내륙 항만은 ICD의 설명이다.","src":"기출 2024-4"},{"x":"농수산물종합유통센터가 통관 기능도 수행한다.","o":"통관 기능은 없다. 수집·포장·가공·보관·수송·판매 기능이다.","src":"기출 2024-4"},{"x":"CY는 LCL 화물을 컨테이너에 넣고 꺼내는 시설이다.","o":"LCL 적입·FCL 분리는 CFS의 일이다. CY는 컨테이너를 인도·인수·보관하는 장소이다.","src":"기출 2024-4"},{"x":"특허보세구역: 일반 개인이 신청하면 지방자치단체장이 특허해 주는 보세구역.","o":"특허보세구역은 세관장이 특허한다.","src":"관세법 제174조"},{"x":"공동집배송단지가 혼합배송으로 차량의 공차율을 증가시킨다.","o":"혼합배송으로 공차율이 감소한다.","src":"기출 2023-2"},{"x":"공동집배송단지가 보관 수요 통합 관리로 업체별 보관 공간 및 관리 비용을 증가시킨다.","o":"보관 공간과 관리 비용이 줄어든다.","src":"기출 2023-2"},{"x":"ICD는 항만지역보다 창고 보관 시설용 토지 매입이 어렵다.","o":"항만지역보다 토지 매입이 쉽다.","src":"기출 2022-4 / 보충(추정)"},{"x":"ICD는 화물의 소단위화로 운송의 비효율이 발생한다.","o":"ICD는 화물을 대단위로 모아 운송 효율을 높인다.","src":"기출 2022-4 / 보충(추정)"},{"x":"복합물류터미널은 화물자동차·철도화차의 공차율이 증가하는 역효과가 상존한다.","o":"복합물류터미널은 공차율을 줄인다.","src":"기출 2025-3 / 보충(추정)"},{"x":"복합물류터미널은 환적기능보다 보관기능 위주이고 물류정보 기능은 포함하지 않는다.","o":"환적·화물정보센터 기능을 수행한다.","src":"기출 2025-3"},{"x":"스마트물류센터: 수출입컨테이너 내륙 통관기지로 항만터미널과 유사한 기능(2025-5 ㄷ)","o":"그 설명은 ICD이다. 스마트물류센터는 인증받은 첨단 물류창고이다.","src":"기출 2025-5"},{"x":"특허보세구역에 세관검사장이 포함된다.","o":"세관검사장은 지정보세구역이다. 특허보세구역은 보세창고·보세공장·보세전시장·보세건설장·보세판매장이다.","src":"관세법 제154조 / 기출 2026-7"}]},"#3":{"묶음":[{"머리":"입지 선정 시 고려사항","줄":[{"t":"입지 선정 단계에서 우선 고려할 것: 지가, 운송비, 시장 규모, 각종 법적 규제.","src":"기출 2021-2"},{"t":"제품의 보관 위치 할당은 센터 내부 운영 문제이지 입지 선정의 우선 고려 사항이 아니다.","src":"기출 2021-2"},{"t":"수요와 공급을 효율적으로 연계할 수 있는 지역을 고른다.","src":"기출 2022-8"},{"t":"노동력 확보가 가능한 지역을 고른다.","src":"기출 2022-8"},{"t":"경제적·자연적·지리적 요인을 고려한다.","src":"기출 2022-8"},{"t":"운송수단의 연계가 쉬운 지역에 입지한다.","src":"기출 2022-8"},{"t":"토지 가격은 고려 요인 가운데 하나이며 최우선 조건이 아니다.","src":"기출 2022-8"}]},{"머리":"입지결정 기법 전체","줄":[{"t":"무게중심법(Center of Gravity): 수요지·공급지의 거리와 물동량을 고려해 총 운송비가 최소가 되는 좌표를 구한다. 총 운송비가 거리에 비례한다고 가정한다.","src":"기출 2021-4, 2023-8"},{"t":"무게중심법은 공급지·수요지의 위치와 반입·반출 물량이 주어져야 한다. 수송비를 입지요인으로 본다.","src":"기출 2023-8"},{"t":"톤-킬로법: 물동량의 무게와 거리를 고려해 수요처·배송센터까지의 거리와 운송량으로 입지를 평가한다. 주관적 요인은 반영하지 못한다.","src":"기출 2024-7, 2025-9"},{"t":"요인평정법(가중점수법): 접근성·지역환경·노동력 등 입지요인별로 가중치를 두고, 가중치를 곱한 요인별 점수로 후보지를 고른다.","src":"기출 2024-7, 2025-9, 2026-8"},{"t":"브라운 & 깁슨법: 입지 영향 요인을 필수적 요인·객관적 요인·주관적 요인으로 나누어 평가한다.","src":"기출 2021-4, 2024-7, 2025-9, 2026-8"},{"t":"총비용 비교법: 입지 대안별 예상비용을 산출해 총비용이 최소인 대안을 고른다.","src":"기출 2021-4, 2024-7, 2025-9, 2026-8"},{"t":"손익분기 도표법: 예상 물동량(입고량 또는 출고량)에 대한 고정비와 변동비를 산출해, 물동량에 따른 총비용이 최소인 대안을 고른다.","src":"기출 2021-4, 2023-9, 2024-7, 2026-8"},{"t":"체크리스트법은 입지 요인을 점검표로 평가하는 방법이다.","src":"기출 2023-9 / 보충"}]},{"머리":"계산: 무게중심법","줄":[{"t":"공식: X = Σ(물동량×X좌표) ÷ Σ물동량, Y = Σ(물동량×Y좌표) ÷ Σ물동량.","src":"기출 2022-6, 2023-17, 2025-8, 2026-10"},{"t":"공급지(생산공장)의 물동량은 수요지 물동량의 합으로 놓고 분자·분모에 모두 넣는다.","src":"기출 2022-6, 2023-17, 2026-10"},{"t":"풀이 순서: ① 공급지 물동량=수요량 합 ② 지점별 물동량×좌표 합 ③ 전체 물동량 합으로 나눔.","src":"기출 2022-6, 2023-17"},{"t":"예(2022-6): 시장 (50,10)·100, (20,50)·200, (10,10)·200, 공장 (100,150)·500 → X=61, Y=88.","src":"기출 2022-6"},{"t":"예(2026-10): 수요지 (5,80)·20, (10,40)·20, (20,10)·10, 공장 (80,60)·50 → (45, 55).","src":"기출 2026-10"}]},{"머리":"계산: 직각거리","줄":[{"t":"직각거리 = |x1−x2| + |y1−y2|. 일별 총이동거리 = Σ(직각거리 × 일별 배송횟수).","src":"기출 2021-16"},{"t":"예(2021-16): 센터 (6,4). 수요지1 (3,8)·2회 → 14, 수요지2 (8,2)·3회 → 12, 수요지3 (2,5)·2회 → 10. 합계 36km.","src":"기출 2021-16"}]}],"함정":[{"x":"토지 가격이 저렴한 지역을 최우선 선정조건으로 고려한다.","o":"토지 가격은 고려 요인의 하나일 뿐 최우선 선정조건이 아니다. 수요·공급 연계, 운송수단 연계, 노동력 확보 등을 함께 본다.","src":"기출 2022-8 / 기출 2021-2, 2022-8"},{"x":"시장경쟁력, 재고통합효과, 설비를 고려하는 동적 입지모형이다.","o":"무게중심법은 수송비를 고려하는 정적(static) 입지모형이다. 시장경쟁력·재고통합효과·설비를 함께 고려하는 것은 동적 모형이다.","src":"기출 2023-8 / 보충(추정)"},{"x":"톤-킬로법은 물동량의 무게와 거리를 고려한 방법으로 입지 제약, 환경 제약 등 의 주관적 요인을 반영할 수 있는 방법이다.","o":"톤-킬로법은 물동량의 무게와 거리를 고려하지만 입지·환경 제약 같은 주관적 요인은 반영하지 못한다. 주관적 요인은 요인평정법·브라운깁슨법에서 다룬다.","src":"기출 2024-7 / 기출 2024-7 / 보충"},{"x":"의사결정나무분석(Decision Tree Analysis): 설문지, 현장인터뷰 등을 통해 소비자들 로부터 의견을 청취하고, 파레토분석을 실시하여 선정하는 방법이다.","o":"설문지·현장인터뷰 등으로 소비자 의견을 듣는 것은 시장조사법이다. 의사결정나무는 의사결정 경로를 분기도로 나타내 기대가치를 비교한다.","src":"기출 2026-8 / 기출 2025-19 / 보충"},{"x":"제품의 보관 위치 할당(물류센터 입지 선정 단계에서 우선 고려할 사항으로)","o":"입지 선정이 아니라 센터 내부 운영·설계 단계의 문제이다.","src":"기출 2021-2"},{"x":"톤-킬로법은 입지 제약, 환경 제약 등의 주관적 요인을 반영할 수 있다.","o":"톤-킬로법은 주관적 요인을 반영하지 못한다.","src":"기출 2024-7 / 보충"},{"x":"톤-킬로법: 입지거점 대안별로 예상비용을 산출하고 총비용이 최소가 되는 대안을 선택(2025-9 선지 1)","o":"그 설명은 총비용 비교법이다.","src":"기출 2025-9"},{"x":"총비용 비교법: 입지요인에 주관적으로 가중치를 설정해 평가(2025-9 선지 3)","o":"그 설명은 요인평정법이다.","src":"기출 2025-9"},{"x":"요소분석법: 고정비와 변동비를 산출해 총비용이 최소인 대안 선택(2025-9 선지 4)","o":"그 설명은 손익분기 도표법이다.","src":"기출 2025-9"},{"x":"손익분기 도표법: 각 수요처와 배송센터까지의 거리와 운송량을 평가해 입지 선택(2025-9 선지 5)","o":"그 설명은 톤-킬로법 계열이다. 손익분기 도표법은 고정비·변동비 비교이다.","src":"기출 2025-9 / 보충(추정)"}]},"#4":{"묶음":[{"머리":"건설 업무 단계","줄":[{"t":"입지분석단계: 지역분석, 시장분석, 정책 및 환경 분석, SWOT 분석.","src":"기출 2021-7"},{"t":"기능분석단계: 취급 물품 특성에 맞춰 물류센터 기능을 분석한다.","src":"기출 2021-7"},{"t":"투자효과분석단계: 시설 규모·운영 방식·경제적 투자 타당성을 분석한다.","src":"기출 2021-7"},{"t":"기본설계단계: 구체적 레이아웃과 작업방식을 설계한다.","src":"기출 2021-7"},{"t":"시공운영단계: 토목·건축 시공 후 테스트와 보완을 거쳐 운영한다.","src":"기출 2021-7"},{"t":"물류거점 분석 단계의 활동: 지역 분석, 수익성 분석, 투자 효과 분석, 거시환경 분석. 하역장비 설치는 시공 단계이다.","src":"기출 2022-12"}]},{"머리":"설계 고려 특성·규모 결정 요인","줄":[{"t":"물류센터 설계 고려요인: 입하능력, 출하시간, 물품 취급횟수, 보관 면적.","src":"기출 2021-8"},{"t":"운영특성: 입고·보관·피킹·배송방법.","src":"기출 2022-7, 2023-5, 2024-8"},{"t":"물품특성: 제품의 크기·무게·가격.","src":"기출 2022-7, 2023-5, 2024-8"},{"t":"주문특성: 주문건수·주문빈도·주문크기.","src":"기출 2024-8, 2025-2"},{"t":"설비특성: 설비종류·자동화 수준.","src":"기출 2022-7, 2023-5, 2025-2"},{"t":"환경특성: 지리적 위치·입지 제약·환경 제약.","src":"기출 2023-5, 2025-2"},{"t":"규모 결정 영향 요인: 자재취급시스템 형태, 통로 요구조건, 재고배치, 현재 및 미래의 제품 출하량, 사무실 공간.","src":"기출 2023-11"},{"t":"규모 산정에는 목표 재고량과 서비스 수준을 함께 고려한다.","src":"기출 2022-7 / 보충(추정)"},{"t":"입지 결정에서는 관련 비용의 최소화를 고려한다.","src":"기출 2022-7"}]},{"머리":"창고(레이아웃) 설계의 기본원칙","줄":[{"t":"직진성의 원칙: 물품·통로·운반기기·사람의 흐름 방향을 직진 중심으로 설계한다.","src":"기출 2025-10, 2026-9"},{"t":"모듈화의 원칙: 화물형태·운반기기·랙·통로입구·기둥간격을 모듈화한다.","src":"기출 2025-10, 2026-9"},{"t":"물품취급 횟수 최소화의 원칙: 취급·운반을 집합화·공동화한다.","src":"기출 2025-10, 2026-9"},{"t":"물품이동 간 고저간격 축소의 원칙: 흐름 과정의 높낮이 차와 횟수를 줄인다.","src":"기출 2025-10, 2026-9"},{"t":"역행교차 회피의 원칙: 물품·운반기기·사람의 흐름이 서로 교차하거나 역주행하지 않게 배치한다.","src":"기출 2025-10, 2026-9"}]},{"머리":"투자타당성 분석 기법","줄":[{"t":"순현재가치법(NPV): 장래 현금흐름의 현재가치에서 초기 투자비용을 뺀 값.","src":"기출 2022-9, 2026-6"},{"t":"내부수익률법(IRR): 편익의 현재가치 합계와 비용의 현재가치 합계가 같아지는(NPV=0) 할인율.","src":"기출 2022-9, 2026-6"},{"t":"투자수익률(ROI): 순수익을 총투자비로 비교한다.","src":"기출 2026-6"},{"t":"비용편익비(B/C): 편익÷비용. 클수록 타당성이 높다.","src":"기출 2026-6 / 보충"},{"t":"자본회수기간법: 투자비를 회수하는 데 걸리는 기간을 본다.","src":"기출 2022-9 / 보충"},{"t":"물류시설 투자의 편익: 운송·보관·하역 비용 절감 등. 비용: 토지 구입비, 건설비, 운영·유지관리비 등.","src":"기출 2026-6"},{"t":"브라운깁슨법·손익분기점법은 입지·비용 분석 기법이며 IRR이 아니다.","src":"기출 2022-9"}]},{"머리":"공공 물류시설 민간투자사업 방식","줄":[{"t":"BTO(Build Transfer Operate): 건설 후 소유권을 국가·지방자치단체에 넘기고, 일정 기간 시설을 운영한 수익으로 투자비를 회수한다.","src":"기출 2023-6"},{"t":"BOT(Build Operate Transfer): 건설 후 투자비를 회수할 때까지 관리·운영하고, 계약기간이 끝나면 국가에 양도한다. 운영 기간 만료 시 소유권이 국가·지방자치단체에 귀속된다.","src":"기출 2023-6, 2026-4"},{"t":"BOO(Build Own Operate): 준공과 동시에 소유권과 운영권이 사업시행자에게 인정된다.","src":"기출 2026-4"},{"t":"BLT(Build Lease Transfer): 건설 후 일정 기간 국가·지방자치단체에 임대해 투자비를 회수하고, 임대기간이 끝나면 소유권을 넘긴다.","src":"기출 2023-6, 2026-4"},{"t":"BTL(Build Transfer Lease): 준공과 동시에 소유권이 국가에 귀속되고, 사업시행자에게 일정 기간 시설관리운영권을 인정하되 국가가 임차해 사용·수익한다.","src":"기출 2026-4 / 보충"}]}],"함정":[{"x":"기본설계단계: 구체적인 레이아웃과 작업방식, 물류비용 정산방법을 설계한다.","o":"기본설계단계: 구체적인 레이아웃과 작업방식, 설비 설계를 한다. 물류비용 정산방법은 기본설계 내용이 아니다.","src":"기출 2021-7 / 보충(추정)"},{"x":"물류센터의 규모 산정 시 목표 재고량은 고려하나 서비스 수준은 고려 대상이 아니다.","o":"물류센터 규모를 정할 때 목표 재고량과 서비스 수준을 모두 고려한다.","src":"기출 2022-7 / 보충(추정)"},{"x":"주문특성은 재고정책, 고객서비스 목표, 투자 및 운영 비용을 반영한다.","o":"주문특성은 주문건수·주문빈도·주문크기를 반영한다.","src":"기출 2023-5 / 기출 2024-8"},{"x":"화물보험 가입 용이성, 신용장 개설 편의성 등 보험ㆍ금융 회사 접근 특성을 고 려한다.","o":"물류센터 설계 고려 특성은 운영·물품·주문·설비·환경이다. 보험·금융 회사 접근 특성은 해당하지 않는다.","src":"기출 2024-8 / 기출 2023-5, 2024-8"},{"x":"비용편익비(Benefit Cost Ratio)는 편익을 비용으로 나눈 비율로, 비용편익비가 작을수록 높은 투자 타당성을 갖는다.","o":"비용편익비(B/C)는 편익÷비용이며 1보다 크고 클수록 투자 타당성이 높다.","src":"기출 2026-6 / 보충"},{"x":"하역장비 설치(물류거점 분석 단계의 활동으로)","o":"하역장비 설치는 시공 단계이다. 거점 분석은 지역·수익성·투자효과·거시환경 분석이다.","src":"기출 2022-12"},{"x":"운영 요인: 지리적 위치, 입지 제약, 인구 등(2025-2 ㄱ)","o":"그 내용은 환경 요인이다. 운영 요인은 입고·보관·피킹·배송방법이다.","src":"기출 2025-2"},{"x":"환경 요인: 입고 방법, 보관 방법, 피킹 방법 등(2025-2 ㄹ)","o":"그 내용은 운영 요인이다.","src":"기출 2025-2"},{"x":"역행교차 회피의 원칙: 흐름의 배치가 서로 교차하거나 역주행이 가능하도록 설계(2025-10 선지 5)","o":"교차·역주행이 없도록 설계한다. 2026-9의 「역행교차 활성화 원칙」도 틀린 말이다.","src":"기출 2025-10, 2026-9"},{"x":"BLT: 준공과 동시에 소유권이 국가에 귀속되고 사업시행자에게 운영권을 인정하되 국가가 임차(2026-4 ㄷ)","o":"그 설명은 BTL이다. BLT는 임대 기간 후 소유권을 이전한다.","src":"기출 2026-4 / 보충"}]},"#5":{"묶음":[{"머리":"창고의 기능","줄":[{"t":"수급조정 기능: 생산과 소비의 시간적 간격을 조정해 일정량이 체류하게 한다. 시간적 효용을 창출한다.","src":"기출 2022-16, 2023-12"},{"t":"가격조정 기능: 수요와 공급을 조정해 가격안정을 도모한다.","src":"기출 2022-16, 2023-12"},{"t":"연결 기능: 물류활동을 연결하는 터미널 역할을 한다.","src":"기출 2022-16"},{"t":"신용기관적 기능: 재고(안전재고)를 확보해 품절을 막고 기업 신용을 높인다.","src":"기출 2022-16, 2023-12"},{"t":"물품을 안전하게 보관하거나 현상을 유지하는 역할(보존 기능).","src":"기출 2023-12"},{"t":"물품을 한 장소에서 다른 장소로 옮겨 장소적 효용을 만드는 것은 운송의 기능이다.","src":"기출 2023-12"},{"t":"보관 기능(품질 특성·영업전략), 품절 예방, 포장·라벨 부착·검품, 운송연계 기능 모두 창고 기능이다.","src":"기출 2024-15"}]},{"머리":"소유·운영 주체별 창고","줄":[{"t":"자가창고: 입지·시설·장비를 자사 물류시스템에 맞게 설계·운영한다. 건설·설비 고정비용이 든다.","src":"기출 2023-13, 2025-12"},{"t":"영업창고: 타인의 화물을 보관한다. 이용자는 초기 건설·설비투자 부담이 없고 비용지출이 명확하다.","src":"기출 2024-14, 2025-12, 2023-13"},{"t":"임대창고: 특정 보관시설을 임대하거나 리스하여 물품을 보관한다. 시장환경에 따라 보관장소를 탄력적으로 운영하기 어렵다.","src":"기출 2022-15, 2023-13, 2025-12"},{"t":"공공창고: 공공기관이 설치·운영하는 창고.","src":"보충(추정)"}]},{"머리":"용도·형태별 창고","줄":[{"t":"보세창고: 관세법에 근거하며 세관장의 특허를 받아 수출입화물을 취급한다. 외국물품·통관 예정 물품을 장치한다.","src":"관세법 제174조, 제183조 / 기출 2023-13, 2025-12"},{"t":"내국물품은 운영인이 세관장에게 신고하면 보세창고에 장치할 수 있다. 1년(제2항 단서 물품은 6개월) 이상 계속 내국물품만 장치하려면 세관장의 승인을 받아야 한다.","src":"관세법 제183조"},{"t":"유통창고: 생산된 제품의 집하·배송 기능을 갖추고 보관·가공·재포장을 한다.","src":"기출 2023-13"},{"t":"자동화창고: 입하부터 출하까지 자동화되고 유닛로드로 처리한다.","src":"기출 2025-12"},{"t":"야적창고: 물품을 노지에 보관한다.","src":"기출 2024-14"},{"t":"수면창고: 하천이나 해수면을 이용해 물품을 보관한다.","src":"기출 2024-14"},{"t":"위험물창고: 고압가스·유독성 물질 등을 보관한다.","src":"기출 2024-14"},{"t":"냉동냉장창고 온도등급에는 C1·C2·C3·F급이 있다. D급은 없다.","src":"기출 2026-14"}]}],"함정":[{"x":"보세창고는 지방자치단체장의 허가를 받은 경우에는 통관되지 않은 내국물품도 장치할 수 있다.","o":"보세창고는 외국물품이나 통관을 하려는 물품을 장치하고, 내국물품은 운영인이 세관장에게 신고하면 장치할 수 있다. 지방자치단체장의 허가가 아니다.","src":"기출 2022-15 / 관세법 제183조"},{"x":"영업창고는 임대료를 획득하기 위해 건립되므로 자가창고에 비해 화주 입장의 창고설계 최적화가 가능하다.","o":"화주 입장에서 창고설계 최적화가 가능한 것은 자가창고이다. 영업창고는 보관료를 받고 타인 화물을 보관한다.","src":"기출 2022-15 / 기출 2023-13, 2025-12"},{"x":"자가창고는 영업창고에 비해 창고 확보와 운영에 소요되는 비용 및 인력문제와 화물량 변동에 탄력적으로 대응할 수 있다.","o":"자가창고는 영업창고에 비해 건설·운영 비용과 인력 부담이 크고 물량 변동에 탄력적으로 대응하기 어렵다.","src":"기출 2022-15 / 기출 2023-13 / 보충"},{"x":"공공창고는 특정 보관시설을 임대하여 물품을 보관하는 창고형태로 민간이 설치 및 운영한다.","o":"공공창고: 정부·지방자치단체 등 공공기관이 설치·운영하는 창고. 시설을 임대하여 보관하는 것은 임대창고이다.","src":"기출 2022-15 / 보충(추정)"},{"x":"물품을 한 장소에서 다른 장소로 이동시키는 물리적 행위를 통해 장소적 효용을 창출한다.","o":"물품을 장소 간 이동시켜 장소적 효용을 창출하는 것은 운송의 기능이다. 창고는 시간적 효용을 창출한다.","src":"기출 2023-12 / 기출 2023-12, 2022-2"},{"x":"영업창고 이용자는 초기에 창고건설 및 설비투자와 관련하여 고정비용이 발생한다.","o":"영업창고 이용자는 초기 건설·설비투자 고정비용이 들지 않는다.","src":"기출 2023-13 / 기출 2025-12"},{"x":"영업창고: 비용지출이 명확하고 초기 창고 건설 및 설비투자 비용이 발생한다.","o":"영업창고는 비용지출이 명확하고 초기 건설·설비투자가 필요 없다.","src":"기출 2025-12 / 기출 2023-13"},{"x":"리스창고: 자기의 화물을 보관하기 위해 설치한 창고.","o":"자기 화물 보관용은 자가창고이다. 리스창고는 임차한 창고이다.","src":"기출 2024-14 / 보충"},{"x":"D급(냉동냉장창고 온도 분류 등급으로)","o":"D급은 없다. C1·C2·C3·F급이 있다.","src":"기출 2026-14"}]},"#6":{"묶음":[{"머리":"랙 종류 전체","줄":[{"t":"파렛트 랙(Pallet Rack): 파렛트 화물을 보관하는 기본 랙.","src":"기출 2022-10, 2022-14"},{"t":"실렉티브 랙(Selective Rack): 모든 파렛트에 직접 접근하는 기본형 랙. 경량 다품종 회전랙이 아니다.","src":"기출 2021-17 / 보충"},{"t":"드라이브인 랙(Drive-in Rack): 지게차가 한 방향에서 2개 이상 깊이의 랙에 들어가 보관·반출한다.","src":"기출 2022-10"},{"t":"드라이브스루 랙(Drive-through Rack): 지게차가 랙의 한 방향으로 진입해 반대 방향으로 퇴출할 수 있다.","src":"기출 2021-17, 2025-15"},{"t":"플로우 랙(Flow Rack): 적입과 인출이 반대 방향에서 이루어지는 선입선출 랙. 롤러·휠이 달리고 중력으로 미끄러진다.","src":"기출 2021-17, 2023-10, 2024-12, 2025-15"},{"t":"캔틸레버 랙(Cantilever Rack, 암 랙): 긴 철재·목재·파이프 같은 장척물 보관에 효율적이다.","src":"기출 2021-17, 2022-10, 2024-12, 2025-15"},{"t":"적층 랙(Mezzanine Rack): 천장이 높은 창고에서 복층 구조로 설치해 공간 활용도를 높인다.","src":"기출 2021-17, 2022-10, 2024-12, 2025-15"},{"t":"캐러셀(Carousel) 랙: 랙 자체가 수평 또는 수직으로 회전해 저장 위치가 입출고(피킹)점으로 이동한다. 가벼운 다품종 소량품에 쓴다.","src":"기출 2022-10, 2024-12, 2026-11"},{"t":"모빌 랙(Mobile Rack): 필요한 통로만 열어 쓰고 불필요한 통로를 없애 면적 효율이 높다. 바닥면·용적 효율이 높고 복수 통로를 둘 수 있다.","src":"기출 2023-10, 2025-15"},{"t":"슬라이딩 랙, 자동 슬라이딩 랙, 고층 랙, 트랜스 로보 시스템도 랙·보관 장비로 출제됐다.","src":"기출 2022-14, 2025-31"},{"t":"이중깊이저장랙(Double Deep Rack) 작업에는 리치포크(Reach Fork) 어태치먼트가 필요하다.","src":"기출 2026-31"}]},{"머리":"오더피킹 출고형태별 적재방식 장비","줄":[{"t":"제1형태(P→P, 파렛트 보관·파렛트 출고): 트랜스 로보, 파렛트 랙, 드라이브인 랙, 고층 랙. 암 랙은 아니다.","src":"기출 2022-14"},{"t":"제4형태(C→C, 케이스 보관·케이스 출고): 자동 슬라이딩 랙, 슬라이딩 랙, 캐로셀 랙, 모빌 랙. 암 랙은 아니다.","src":"기출 2025-31"}]}],"함정":[{"x":"실렉티브랙(Selective Rack): 경량 다품종 물품의 입출고에 적합한 수평 또는 수직의 회전랙이다.","o":"실렉티브랙: 각 파렛트에 직접 접근해 입출고하는 가장 기본적인 파렛트 랙이다. 경량 다품종 회전은 캐러셀 설명이다.","src":"기출 2021-17 / 기출 2021-17 / 보충"},{"x":"파렛트 랙(Pallet Rack): 파렛트 화물을 한쪽 방향에서 넣으면 중력에 의해 미끄 러져 인출할 때는 반대방향에서 화물을 반출할 수 있다.","o":"파렛트 랙: 파렛트 화물을 보관하는 기본 랙. 한쪽에서 넣어 반대쪽으로 인출하는 중력식 랙은 플로우 랙이다.","src":"기출 2022-10 / 기출 2021-17, 2025-15"},{"x":"파렛트가 랙 내에서 경사면을 이용하여 이동하는 방식으로 선입선출이 요구되는 제품에 적합하다.","o":"파렛트가 경사면으로 이동하는 선입선출 랙은 플로우 랙이다. 모빌랙(이동랙)은 불필요한 통로를 없애 면적 효율을 높인다.","src":"기출 2023-10 / 기출 2023-10, 2025-15"},{"x":"직선으로 수평 이동하는 랙이며, 도서관 등에서 통로면적을 절약하는데 효과적 이다.","o":"도서관식으로 직선 수평 이동하며 통로 면적을 줄이는 랙은 모빌 랙 계열의 설명이다. 이 문항의 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 출제 오답(바른 설명 미확인, 검수 필요)"},{"x":"선입선출의 목적으로 격납 부분에 롤러, 휠 등을 장착하여 반입과 반출이 반대 방향에서 이루어진다.","o":"롤러·휠로 반입·반출이 반대 방향에서 이루어지는 선입선출 랙은 플로우 랙이다. 이 문항 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 기출 2021-17, 2025-15 / 검수 필요"},{"x":"랙 자체가 수평 또는 수직방향으로 회전하여 저장 위치가 지정된 입출고장소로 이동 가능한 랙이며, 가벼운 다품종 소량품에 많이 적용된다.","o":"랙 자체가 회전하며 입출고점으로 이동하는 랙은 캐러셀이다. 이 문항 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 기출 2026-11 / 검수 필요"},{"x":"파이프, 목재 등의 장척물 보관에 적합하도록 랙 구조물에 암(arm)이 설치되어 있다.","o":"파이프·목재 등 장척물용 암이 달린 랙은 캔틸레버 랙(암 랙)이다. 이 문항 지문은 랙 이름이 빠져 있다.","src":"기출 2024-12 / 기출 2022-10 / 검수 필요"},{"x":"플로우 랙 설명을 파렛트 랙에(2022-10)","o":"파렛트 랙은 기본 보관 랙이다. 한쪽에서 넣어 중력으로 반대쪽에서 꺼내는 것은 플로우 랙이다.","src":"기출 2022-10"},{"x":"드라이브스루 랙: 천정이 높은 창고의 공간 활용도를 높이기 위한 복층구조의 랙(2025-15)","o":"복층구조 랙은 적층 랙이다. 드라이브스루 랙은 한 방향 진입, 반대 방향 퇴출이다.","src":"기출 2025-15"},{"x":"적층 랙: 지게차가 랙의 한 방향으로 진입해서 반대 방향으로 퇴출(2025-15)","o":"그 설명은 드라이브스루 랙이다.","src":"기출 2025-15"},{"x":"암 랙(Arm Rack)을 파렛트 단위 입출고(P→P)·케이스 단위(C→C) 적재 장비로","o":"암 랙은 두 경우 모두 해당하지 않는다(장척물용).","src":"기출 2022-14, 2025-31"}]},"#7":{"묶음":[{"머리":"AS/RS 구성 장치","줄":[{"t":"랙: 자동화 창고에서 화물 보관 구조물. 빌딩 랙(Building Rack)과 유닛 랙(Unit Rack)이 있다.","src":"기출 2023-16"},{"t":"스태커 크레인(Stacker Crane): 랙과 랙 사이 통로를 왕복하며 수평·수직으로 동시에 움직인다. 승강장치와 포크장치가 달린 핵심 입출고 장치이며 컴퓨터로 저장·반출한다.","src":"기출 2021-13, 2023-16, 2024-31, 2026-12"},{"t":"트래버서(Traverser): 스태커 크레인을 다른 통로로 옮겨 주는 횡행 장치.","src":"기출 2023-16 / 보충(추정)"},{"t":"무인반송차(AGV): 무인으로 물품을 운반·이동한다. 고정경로 혹은 유도방식으로 보관/반출 품목을 입출고 컨베이어와 연결한다.","src":"기출 2023-16, 2024-30, 2026-12"},{"t":"보관단위(Unit): 파렛트형, 버킷형, 레인형, 셀형.","src":"기출 2023-16"},{"t":"셀(Cell): 랙 속에서 화물이 저장되는 단위 공간.","src":"기출 2026-12"}]},{"머리":"운행 명령 방식","줄":[{"t":"단일명령(Single Command): 스태커 크레인이 1회 운행에 입고나 출고 중 하나만 수행한다.","src":"기출 2021-13, 2026-12"},{"t":"이중명령(Dual Command): 1회 운행으로 저장과 반출을 모두 수행한다.","src":"기출 2021-13, 2026-12"}]},{"머리":"저장위치 할당 방식 전체","줄":[{"t":"임의위치저장(Randomized Storage): 입출고 빈도와 상관없이 빈 위치에 임의로 저장한다. 전체 저장 소요 공간이 적다.","src":"기출 2021-13, 2024-11, 2026-13"},{"t":"지정위치저장(Dedicated Storage): 품목별 저장 소요 공간과 단위시간당 평균 입출고 횟수를 고려해 저장위치를 미리 지정한다. 소요 공간이 임의위치저장보다 크거나 같다.","src":"기출 2024-11, 2026-13"},{"t":"등급별저장(Class-based Storage): 입출고 빈도 기준으로 등급을 나누고, 빈도 높은 등급을 입출고점 가까이 둔다. 같은 등급 안에서는 임의위치저장을 쓴다.","src":"기출 2024-11, 2026-13"},{"t":"근거리 우선저장(Closest Open Location Storage): 입출고점에 가장 가까운 빈 곳부터 할당한다.","src":"기출 2026-13"}]},{"머리":"계산: 가동률","줄":[{"t":"가동률 = 처리 소요시간 ÷ 가용시간. 이중명령 1회는 저장 1건과 반출 1건을 처리한다.","src":"기출 2024-10"},{"t":"풀이 순서: ① 전체 지시(저장+반출) 건수 ② 이중명령 비율만큼 쌍으로 묶어 이중명령 횟수 ③ 나머지는 단일명령 횟수 ④ 횟수×사이클 시간 합 ÷ 60분.","src":"기출 2024-10"},{"t":"예(2024-10): 저장 10+반출 10=20건. 이중 60% → 12건=6회×5분=30분. 단일 8회×3분=24분. 합계 54분 ÷ 60분 = 90%.","src":"기출 2024-10"}]},{"머리":"계산: 저장소요공간","줄":[{"t":"임의위치저장 소요공간 = 기간별 전 품목 필요공간 합계 중 최댓값.","src":"기출 2026-33"},{"t":"지정위치저장 소요공간 = 품목별 기간 최대 필요공간의 합.","src":"기출 2026-33"},{"t":"예(2026-33): 주별 합 105·104·107·106·110 → 임의 110. 품목별 최대 A26·B25·C22·D36·E26 → 지정 135.","src":"기출 2026-33"}]}],"함정":[{"x":"스태커 크레인(Stacker Crane): 창고의 통로 공간을 수평 방향으로만 움직이는 저장/반출 기기이다.","o":"스태커 크레인: 랙 사이 통로를 수평 방향과 수직 방향으로 함께 움직이는 저장/반출 기기이다.","src":"기출 2021-13 / 기출 2024-31, 2026-12"},{"x":"단일명령(Single Command) 방식: 1회 운행으로 저장과 반출 작업을 동시에 수행 하는 방식이다.","o":"단일명령 방식: 1회 운행에 저장 또는 반출 중 하나만 수행한다.","src":"기출 2021-13 / 기출 2026-12"},{"x":"이중명령(Dual Command) 방식: 2회 운행으로 저장과 반출 작업을 순차적으로 모두 수행하는 방식이다.","o":"이중명령 방식: 1회 운행으로 저장과 반출을 모두 수행한다.","src":"기출 2021-13 / 기출 2026-12, 2024-10"},{"x":"지정위치저장(Dedicated Storage) 방식: 물품의 입출고 빈도를 기준으로 저장위치를 등급(Class)으로 나누고 등급별로 저장위치를 결정하는 방식이다.","o":"지정위치저장 방식: 품목마다 저장위치를 고정해 둔다. 입출고 빈도로 등급을 나누어 등급별로 위치를 정하는 것은 등급별저장 방식이다.","src":"기출 2021-13 / 기출 2024-11, 2026-13"},{"x":"트래버서(Traverser)는 보관품의 입출고 시 작업장부터 랙까지 연결시켜주는 반송장치이다.","o":"트래버서(Traverser): 스태커 크레인을 다른 통로로 옮겨 주는 횡행 장치이다. 작업장에서 랙까지 연결 반송하는 것은 컨베이어·AGV 등이다.","src":"기출 2023-16 / 보충(추정)"},{"x":"등급별저장(class-based storage)방식은 보관품목의 단위당 경제적 가치를 기준 으로 등급을 설정한다.","o":"등급별저장은 입출고 빈도(회전율)를 기준으로 등급을 나눈다.","src":"기출 2024-11 / 기출 2026-13"},{"x":"이중명령(Dual Command) 방식: 스태커 크레인이 입고나 출고를 2개씩 수행하는 방식이다.","o":"이중명령 방식: 스태커 크레인이 1회 운행으로 입고와 출고를 각 1건씩 함께 수행한다.","src":"기출 2026-12 / 기출 2024-10, 2026-12"},{"x":"트래버서: 보관품의 입출고 시 작업장부터 랙까지 연결시켜 주는 반송장치(2023-16)","o":"트래버서는 스태커 크레인을 통로 간 옮기는 장치이다. 작업장-랙 연결은 컨베이어·AGV가 한다.","src":"기출 2023-16 / 보충(추정)"},{"x":"지정위치저장 방식: 입출고 빈도를 기준으로 등급으로 나누고 등급별로 저장위치를 결정","o":"그 설명은 등급별저장이다.","src":"기출 2021-13"},{"x":"등급별저장 방식은 단위당 경제적 가치를 기준으로 등급을 설정한다.","o":"입출고 빈도(회전율)를 기준으로 등급을 설정한다.","src":"기출 2024-11"}]},"#8":{"묶음":[{"머리":"오더피킹 방식 전체","줄":[{"t":"1인 1건 피킹(싱글 오더 피킹): 피커 한 사람이 주문 전표 1건에 요구된 물품을 모두 피킹한다.","src":"기출 2024-17, 2026-15"},{"t":"일괄 오더 피킹: 여러 건의 주문 전표를 모아 한꺼번에 피킹한다.","src":"기출 2021-10, 2024-17"},{"t":"총량 오더 피킹: 여러 주문을 합산해 품목별 총량을 한 번에 피킹하고 주문별로 나눈다. 1건의 주문마다 모으는 방식이 아니다.","src":"기출 2024-17 / 보충"},{"t":"존(Zone) 피킹: 피커마다 담당 구역(선반 작업범위)을 정해 두고 자기 구역의 물품만 피킹한다.","src":"기출 2021-10, 2024-17"},{"t":"릴레이(Relay) 피킹: 전표에서 해당 피커가 담당하는 품목(분담한 물품 종류)만 피킹하고 다음 피커에게 넘긴다.","src":"기출 2021-10, 2024-17, 2026-15"},{"t":"디지털 피킹(DPS): 전표 없이 피킹하는 방식. 다품종 소량·다빈도 피킹에 효과적이다.","src":"기출 2021-10, 2026-18"},{"t":"차량탑승피킹: 피킹트럭에 탑승해 피킹한다. 보관시설의 공간활용도가 높다.","src":"기출 2021-10 / 보충(추정)"}]},{"머리":"DPS · DAS","줄":[{"t":"DPS(Digital Picking System): 피킹 대상 품목 수량을 디지털 표시기에 표시해 피킹하도록 지원한다.","src":"기출 2023-15, 2026-18"},{"t":"DPS 구성: 표시장치(수량표시부)와 응답장치. 표시된 수량만큼 피킹한 뒤 완료버튼을 누른다.","src":"기출 2026-18"},{"t":"DPS는 작동방식에 따라 대차식, 구동 컨베이어식, 무구동 컨베이어식으로 나눈다.","src":"기출 2023-15"},{"t":"DPS는 소품종 대형·소빈도가 아니라 다품종 소량·다빈도 품목에 효과적이다.","src":"기출 2021-10, 2026-18"},{"t":"DAS(Digital Assorting System): 분배할 물품의 순서에 따라 작업자에게 분류정보를 제공해 신속한 분배를 지원한다.","src":"기출 2023-15"},{"t":"멀티 다품종 DAS: 많은 고객에게 배송하기 위한 분배 과정을 지원하며 합포장에 적합하다.","src":"기출 2023-15"}]},{"머리":"자동분류시스템","줄":[{"t":"분류시스템: 화물을 품종별·발송처별·고객별·목적지별로 식별·구분한다. 소량·다빈도 배송 요구가 늘며 중요도가 커진다.","src":"기출 2021-34"},{"t":"분류 방식 중 동작에 의한 분류: 밀어내는 방식, 다이버트 방식, 이송 방식, 틸트 방식. 바코드 방식은 동작에 의한 분류가 아니다.","src":"기출 2024-36, 2025-34"},{"t":"팝업(Pop-up) 방식: 컨베이어 아래의 롤러·휠·체인 사이 분기장치가 올라와 물품을 들어 올려 방향을 바꾼다. 하부면 손상에 약한 화물에는 부적합하다.","src":"기출 2021-11, 2023-38, 2026-35"},{"t":"푸시오프(Push-off) 방식: 분류지점에 직각 방향으로 암(Arm)을 설치해 밀어낸다.","src":"기출 2023-38"},{"t":"슬라이딩슈(Sliding-shoe) 방식: 반송면 아래 슈가 단위화물과 함께 이동하면서 압출한다. 전환 흐름이 부드러워 손상 가능성이 낮다.","src":"기출 2021-11, 2023-38, 2025-13"},{"t":"크로스벨트(Cross-belt) 방식: 레일을 주행하는 연속된 캐리어 위 소형 벨트컨베이어를 레일과 교차하는 방향으로 구동해 분류한다.","src":"기출 2022-29, 2023-38, 2026-35"},{"t":"틸팅(Tilting) 방식: 트레이·슬라이드 등을 경사지게 해 화물을 떨어뜨려 분류한다. 트레이 틸팅은 고속 주행 트레이를 기울인다.","src":"기출 2021-11, 2025-13, 2026-35"},{"t":"다이버터(Diverter) 방식: 안내판·바를 설치해 화물이 가로막혀 방향을 바꾸게 한다. 다양한 형상의 화물을 분류할 수 있고 구조가 팝업보다 단순하다.","src":"기출 2021-11, 2022-29, 2026-35"},{"t":"다이버터 바 스윙 방식: 컨베이어 측면에 바를 설치해 목적방향으로 화물을 이동시킨다.","src":"기출 2026-35"}]}],"함정":[{"x":"차량탑승피킹: 파렛트 단위로 피킹하는 유닛로드시스템(Unit Load System)이며, 피킹트럭에 탑승하여 피킹함으로써 보관시설의 공간활용도가 낮다.","o":"차량탑승피킹: 피킹트럭에 탑승해 고층 랙에서 피킹하므로 보관시설의 공간활용도가 높다.","src":"기출 2021-10 / 보충(추정)"},{"x":"다이버터(Diverter) 방식은 팝업 방식에 비하여 구조가 상대적으로 복잡하다.","o":"다이버터 방식은 가이드벽·바로 방향을 바꾸는 단순한 구조이고 팝업 방식이 구조가 상대적으로 복잡하다.","src":"기출 2021-11 / 기출 2021-11"},{"x":"크로스벨트(Cross belt) 방식: 컨베이어 반송면의 아래 방향에서 벨트 등의 분기장 치가 나오는 방식으로 하부면의 손상 및 충격에 취약한 화물에는 적합하지 않다.","o":"크로스벨트 방식: 레일을 주행하는 캐리어 위 소형 벨트컨베이어를 교차 방향으로 구동해 분류한다. 아래에서 분기장치가 나오는 것은 팝업 방식이다.","src":"기출 2022-29 / 기출 2022-29, 2023-38, 2026-35"},{"x":"팝업(Pop-up) 방식: 레일을 주행하는 연속된 캐리어 상의 소형벨트 컨베이어를 레일과 교차하는 방향으로 구동시켜 단위화물을 내보내는 방식이다.","o":"팝업 방식: 컨베이어 아래에서 휠·체인 등 분기장치가 올라와 방향을 바꾼다. 소형벨트를 교차 구동하는 것은 크로스벨트 방식이다.","src":"기출 2022-29 / 기출 2023-38, 2026-35"},{"x":"틸팅(Tilting) 방식: 반송면에 튀어나온 기구를 넣어 단위화물을 함께 이동시키면 서 압출하는 방식이다.","o":"틸팅 방식: 트레이·슬라이드 등을 기울여 화물을 떨어뜨린다. 반송면의 기구가 화물과 함께 이동하며 압출하는 것은 슬라이딩슈 방식이다.","src":"기출 2022-29 / 기출 2023-38, 2025-13"},{"x":"슬라이딩슈(Sliding-shoe) 방식: 여러 형상의 화물을 수직으로 나누어 강제적으 로 분류하므로 충격에 취약한 정밀기기나 깨지기 쉬운 물건은 피해야 한다.","o":"슬라이딩슈 방식은 화물을 부드럽게 전환시켜 손상 가능성이 낮다.","src":"기출 2022-29 / 기출 2021-11"},{"x":"멀티 릴레이 DAS는 주문 단위로 출하박스를 투입하여 피킹하는 방식으로 작업 자의 이동이 최소화된다.","o":"멀티 릴레이 DAS: 구역별 작업자가 이어서 분배하는 방식으로 이 설명은 어울리지 않는다.","src":"기출 2023-15 / 출제 오답(바른 설명 미확인)"},{"x":"틸팅 방식(Tilting Type)은 벨트, 트레이, 슬라이드 등의 바닥면을 개방하여 물품을 분류한다.","o":"틸팅 방식은 트레이·벨트·슬라이드 등을 기울여 분류한다. 바닥면을 개방하는 방식과는 다르다.","src":"기출 2023-38 / 기출 2025-13, 2026-35 / 보충(추정)"},{"x":"다이버터 푸셔 방식(Diverter Pusher Type)은 컨베이어 하부에 푸셔(Pusher)를 설치하여 분류지점에 화물이 위치하면 푸셔로 화물을 들어올려 방향을 전환시켜 주는 방식이다.","o":"다이버터 푸셔 방식은 컨베이어 측면에서 푸셔로 화물을 밀어 방향을 바꾼다. 하부에서 들어올리는 것은 팝업 방식이다.","src":"기출 2026-35 / 기출 2026-35 / 보충(추정)"},{"x":"총량 오더 피킹: 1건의 주문마다 물품을 피킹해서 모으는 방법","o":"1건 주문마다 모으는 것은 1인 1건 피킹이다. 총량 피킹은 여러 주문의 품목을 합쳐 한 번에 피킹한다.","src":"기출 2024-17"},{"x":"DPS는 대형품목 소빈도 피킹에 효과적이다.","o":"다품종 소량·다빈도 피킹에 효과적이다.","src":"기출 2026-18"},{"x":"바코드 방식이 동작에 의한 분류 방식이다.","o":"동작 분류는 밀어내기·다이버트·이송·틸트이다.","src":"기출 2024-36, 2025-34"},{"x":"슬라이딩슈 방식은 정밀기기나 깨지기 쉬운 물건은 피해야 한다.","o":"슬라이딩슈는 전환이 부드러워 손상 가능성이 낮다.","src":"기출 2021-11"},{"x":"컨베이어 하부에서 푸셔로 화물을 들어올려 방향을 전환(다이버터 푸셔)","o":"하부에서 들어 올리는 것은 팝업 방식이다.","src":"기출 2026-35 / 보충(추정)"}]},"#9":{"묶음":[{"머리":"WMS의 기능","줄":[{"t":"WMS(Warehouse Management System): 입출고관리, 재고 및 로케이션관리, 반품관리, 물류센터 지표관리를 종합 수행한다.","src":"기출 2025-14, 2026-17"},{"t":"입고관리·위치관리·재고관리·출고관리 기능.","src":"기출 2025-14"},{"t":"랙(Rack)·셀(Cell)별 재고를 실시간으로 관리한다.","src":"기출 2023-14"},{"t":"정확한 위치정보로 창고 내 피킹·포장작업을 지원한다.","src":"기출 2023-14"},{"t":"입고 후 보관의 원칙에 따라 최적 장소를 골라 저장한다.","src":"기출 2023-14"},{"t":"물동량 증감에 따른 인력계획 수립과 모니터링을 지원한다.","src":"기출 2023-14"},{"t":"피킹관리, 주문진척관리, 자동발주시스템 같은 주문관련 기능을 수행한다.","src":"기출 2025-14"},{"t":"전사적 자원관리시스템(ERP)과 연계해 자동화 범위를 넓히고 정보 가용성을 높인다.","src":"기출 2025-14"},{"t":"시설운영의 효율적 관리와 공간·설비 활용도가 향상된다.","src":"기출 2025-14"},{"t":"WMS 도입 효과: 피킹·출하 효율이 높아지고, 운송수단과의 연계가 쉬워지고, 입하·검품이 쉬워지고, 로케이션 관리가 쉬워진다. 화물파손 위험은 낮아진다.","src":"기출 2024-16"},{"t":"고객 주문내역의 운송수단을 고려한 최적 경로 설정은 WMS 기능이 아니다(TMS).","src":"기출 2023-14 / 보충"},{"t":"자동발주시스템은 EOS, 유연생산시스템은 FMS, 통합생산관리시스템은 MES, 디지털분배시스템은 DAS이다.","src":"기출 2026-17"}]},{"머리":"WMS 패키지(기성제품) 구매 시 고려요인","줄":[{"t":"커스터마이징 용이성, 초기투자비용, 기존 자사 물류정보시스템과의 연계성, 유지보수비용.","src":"기출 2021-15"},{"t":"기성제품의 개발 배경은 고려 요인이 아니다.","src":"기출 2021-15"}]},{"머리":"물류센터 작업 계획 수립 세부 항목","줄":[{"t":"화물 형태: 포장 여부, 포장 방법, 소요 설비.","src":"기출 2022-11"},{"t":"하역 방식: 하역 자동화 수준, 하역 설비 종류·규격.","src":"기출 2022-11"},{"t":"검수 방식: 검수 기준, 검수 작업 방법, 소요 설비.","src":"기출 2022-11"},{"t":"피킹 및 분류: 피킹 기준, 피킹 방법, 소팅 설비.","src":"기출 2022-11"},{"t":"평치·선반·특수 시설 사용 여부는 보관 방식 항목이다. 출하 차량 동선 항목의 내용이 아니다.","src":"기출 2022-11 / 보충(추정)"}]},{"머리":"물류센터 운영 효과","줄":[{"t":"리드타임 단축으로 고객 만족도가 오른다.","src":"기출 2024-5"},{"t":"적정 재고량을 유지하면서 고객니즈에 맞는 서비스를 제공한다.","src":"기출 2024-5"},{"t":"물류센터 수가 늘면 총 안전재고량과 납기준수율이 모두 증가한다.","src":"기출 2024-5"},{"t":"물류센터 운영 전에 비해 공차율이 감소한다.","src":"기출 2024-5"}]},{"머리":"크로스 도킹(Cross Docking)","줄":[{"t":"입고된 물품을 보관하지 않고 바로 출고하는 방식.","src":"기출 2024-13, 2025-11 / 보충"},{"t":"재고 회전율이 증가하고 재고수준·리드타임이 감소한다. 유통업체의 불필요한 재고를 줄인다.","src":"기출 2024-13, 2025-11"},{"t":"장기적으로 센터의 저장 공간을 줄일 수 있다. 기계설비 보강과 정보기술 도입 투자가 필요할 수 있다.","src":"기출 2024-13"},{"t":"입고 품목의 출하지가 알려져 있을 때 더 효과적이다.","src":"기출 2024-13"},{"t":"파렛트 크로스 도킹은 기계설비와 정보기술의 적용이 필요하다. 공급처와 수요처의 정보공유가 필요하다.","src":"기출 2025-11"}]}],"함정":[{"x":"고객주문내역 상의 운송수단을 고려한 최적의 경로를 설정하여 비용과 시간을 절감하도록 지원한다.","o":"WMS는 창고 내부 입고·보관·피킹·출고를 관리한다. 운송수단을 고려한 최적 경로 설정은 운송관리시스템(TMS)의 기능이다.","src":"기출 2023-14 / 보충"},{"x":"각각의 공장에서 소비지까지 제품을 개별 수송하므로 손상, 분실, 오배송이 감소 한다.","o":"물류센터를 거치면 공장별 개별 수송 대신 통합 수송을 하므로 손상·분실·오배송이 줄어든다는 서술이어야 한다. 제시문은 개별 수송을 전제로 한 오답.","src":"기출 2024-5 / 기출 2024-5 / 보충"},{"x":"물류센터의 재고 회전율이 감소한다.","o":"크로스도킹은 재고 회전율을 높이고 재고수준·리드타임을 줄인다.","src":"기출 2024-13 / 기출 2024-13, 2025-11"},{"x":"기존의 독립된 구매관리시스템, 생산관리시스템, 인사관리시스템 및 영업관리 시스템을 통합하여 관리한다.","o":"구매·생산·인사·영업관리 시스템을 통합 관리하는 것은 ERP이다. WMS는 창고 업무를 다룬다.","src":"기출 2025-14 / 기출 2025-14 / 보충"},{"x":"WMS 도입으로 화물파손에 대한 위험성이 높아진다.","o":"화물파손 위험성은 낮아진다.","src":"기출 2024-16"},{"x":"기성제품(패키지)의 개발 배경(WMS 패키지 구매 시 고려 요인으로)","o":"고려 요인이 아니다. 커스터마이징·초기투자비·연계성·유지보수비를 본다.","src":"기출 2021-15"},{"x":"출하 차량 동선 - 평치, 선반 및 특수 시설의 사용 여부(작업 계획 세부 고려사항)","o":"평치·선반 사용 여부는 보관 방식 항목이다.","src":"기출 2022-11 / 보충(추정)"},{"x":"일일 처리량이 적을 때 적합한 방식은 파렛트 크로스 도킹이다.","o":"출제 오답(바른 구분 미확인)","src":"기출 2025-11"}]},"#10":{"묶음":[{"머리":"집중구매 · 분산구매","줄":[{"t":"집중구매방식: 본사가 공통품목을 일괄 구매한다. 대량 구매가 가능하고 가격·거래조건이 유리하다.","src":"기출 2021-23, 2022-18, 2024-21"},{"t":"집중구매방식은 구입 절차를 표준화하기 쉽고, 공통자재의 표준화·단순화가 가능하다.","src":"기출 2024-21"},{"t":"집중구매방식은 수요량이 많은 품목, 수량할인이 있는 품목에 적합하다.","src":"기출 2021-23, 2022-18"},{"t":"분산구매방식: 사업장별 독립적 구매가 가능하고, 사업장의 특수한 요구를 반영하기 쉽다.","src":"기출 2022-18, 2024-21"},{"t":"분산구매방식은 긴급수요에 대처하기 유리하다.","src":"기출 2024-21"}]},{"머리":"MRP(자재소요계획)","줄":[{"t":"MRP는 주생산계획(MPS)을 기초로 완제품 생산에 필요한 자재·구성부품의 종류·수량·시기를 계획한다.","src":"기출 2024-19, 2025-16"},{"t":"MRP 입력: 주생산계획, 자재명세서(BOM), 재고기록파일.","src":"기출 2024-19, 2025-16"},{"t":"MRP는 소요자재를 언제 발주할지 알려 준다. 재고수준의 최소화를 목표로 한다.","src":"기출 2024-19"},{"t":"MRP를 확장해 사업계획과 부문별 계획을 연결한 것이 제조자원계획(MRP II)이다.","src":"기출 2024-19"},{"t":"원자재·반제품 등 모든 자재의 소요량을 산정해 조달계획을 세운다.","src":"기출 2025-16"},{"t":"기업 내 모든 인적·물적 자원의 통합관리는 ERP의 설명이다.","src":"기출 2025-16"},{"t":"정리·정돈·청소·청결·습관화(5S)는 MRP가 아니다.","src":"기출 2025-16"}]},{"머리":"계산: 순소요량","줄":[{"t":"순소요량 = 총소요량 − 예정입고량 − 가용재고.","src":"기출 2023-20, 2025-26"},{"t":"부품 총소요량 = 완제품 소요량 × 완제품 1개당 부품 수.","src":"기출 2023-20, 2025-26"},{"t":"예(2023-20): K 50개, X 2개/Y 3개 구성. X=100−10−5=85, Y=150−20−0=130.","src":"기출 2023-20"},{"t":"예(2025-26): A 60개, X 3개/Y 4개. X=180−20−10=150, Y=240−30=210.","src":"기출 2025-26"}]}],"함정":[{"x":"분산구매방식은 본사의 공통품목을 일괄적으로 구매하기에 적합하다.","o":"집중구매방식이 본사의 공통품목을 일괄 구매하기에 적합하다.","src":"기출 2021-23 / 기출 2021-23, 2024-21"},{"x":"집중구매방식은 분산구매방식보다 사업장별 독립적 구매가 가능하다.","o":"분산구매방식이 집중구매방식보다 사업장별 독립적 구매가 가능하다.","src":"기출 2021-23 / 기출 2021-23"},{"x":"분산구매방식은 구매량에 따라 가격차가 큰 품목의 대량 구매에 적합하다.","o":"구매량에 따라 가격차가 큰 품목의 대량 구매는 집중구매방식에 적합하다.","src":"기출 2021-23 / 기출 2021-23"},{"x":"분산구매방식은 집중구매방식 보다 대량 구매가 이루어지기 때문에 가격 및 거래 조건이 유리하다.","o":"집중구매방식이 분산구매방식보다 대량 구매라 가격·거래 조건이 유리하다.","src":"기출 2021-23 / 기출 2021-23, 2024-21"},{"x":"사업장별 다양한 요구를 반영하여 구매하기에 용이하다.","o":"사업장별 다양한 요구를 반영하기 쉬운 것은 분산구매방식이다.","src":"기출 2022-18 / 기출 2024-21"},{"x":"사업장별 독립적 구매에 유리하나 수량할인이 있는 품목에는 불리하다.","o":"집중구매방식이 수량할인이 있는 품목에 유리하다.","src":"기출 2022-18 / 기출 2021-23, 2024-21"},{"x":"전사적으로 집중구매하기 때문에 가격 및 거래조건이 불리하다.","o":"집중구매는 대량 구매라 가격 및 거래조건이 유리하다.","src":"기출 2022-18 / 기출 2024-21"},{"x":"구매절차의 표준화가 가능하여 긴급조달이 필요한 자재의 구매에 유리하다.","o":"집중구매는 구매절차 표준화에 유리하지만 긴급조달에는 불리하다. 긴급수요에 유리한 쪽은 분산구매이다.","src":"기출 2022-18 / 기출 2024-21"},{"x":"MRP는 재고수준의 최대화를 목표로 한다.","o":"MRP는 재고수준의 최소화를 목표로 한다.","src":"기출 2024-19 / 기출 2024-19"},{"x":"분산구매방식은 긴급수요에 대처하기 불리하다.","o":"분산구매방식은 긴급수요에 대처하기 유리하다.","src":"기출 2024-21 / 기출 2022-18, 2024-21"}]},"#11":{"묶음":[{"머리":"정성적 예측방법 전체","줄":[{"t":"정성적: 델파이법, 시장조사법, 패널조사법, 역사적 유추법, 라이프사이클 유추법, 경영자판단법, 판매원이용법, 전문가조사법.","src":"기출 2021-29, 2022-21, 2023-24, 2026-24"},{"t":"델파이법: 전문가들에게 설문을 반복해 의견을 모으는 방법.","src":"기출 2021-29, 2026-24 / 보충"},{"t":"시장조사법: 설문지·현장인터뷰 등으로 소비자 자료를 수집·분석해 가설을 검증한다. 신제품이나 새로운 시장에 소개되는 제품에 많이 쓴다.","src":"기출 2023-24, 2025-19"},{"t":"라이프사이클 유추법: 상품 수명주기 기간별 과거 매출 증감 폭을 기준으로 수요량을 유추한다.","src":"기출 2022-21"},{"t":"역사적 유추법: 유사 제품의 과거 자료로 신제품의 수요를 정성적으로 예측한다.","src":"기출 2025-19 / 보충"},{"t":"전문가조사법은 타협이나 절충으로 예측 정확도가 낮아질 수 있다.","src":"기출 2025-19"}]},{"머리":"정량적 예측방법 전체","줄":[{"t":"정량적: 시계열분석(이동평균법, 가중이동평균법, 지수평활법)과 인과모형(회귀분석).","src":"기출 2021-29, 2022-21, 2023-24, 2024-18, 2026-24"},{"t":"단순이동평균법: 예측 기간 직전 일정 기간의 시계열 평균값으로 예측한다.","src":"기출 2023-24"},{"t":"가중이동평균법: 먼 과거는 낮은 가중치, 가까운 과거는 높은 가중치를 준다.","src":"기출 2022-21, 2023-24, 2025-19"},{"t":"지수평활법: 관찰된 실제수요와 이전 예측치에 가중치를 두어 새 예측치를 구한다.","src":"기출 2025-19"},{"t":"회귀분석: 원인과 결과 관계를 가진 두 요소의 과거 변화량으로 인과관계를 분석하는 정량적 방법.","src":"기출 2021-29, 2022-21, 2026-24"}]},{"머리":"시계열의 구성요소","줄":[{"t":"수준(level): 추세·계절·순환·무작위 요인을 제외한 평균적 수요량.","src":"기출 2024-18"},{"t":"추세(trend): 수요가 계속 증가하거나 감소하는 경향.","src":"기출 2024-18"},{"t":"계절적(seasonal) 요인: 수요 변화가 규칙적으로 반복되는 현상.","src":"기출 2024-18"},{"t":"순환적(cyclical) 요인: 수년 단위 경기 변동 같은 장기 반복 변화. 단기 불규칙 변화는 무작위 요인.","src":"기출 2024-18 / 보충"}]},{"머리":"계산: 수요예측","줄":[{"t":"지수평활법: 새 예측치 = 이전 예측치 + α × (실제 − 이전 예측치) = α×실제 + (1−α)×이전 예측치.","src":"기출 2021-20, 2022-19, 2024-20, 2025-27, 2026-23"},{"t":"풀이 순서: 조건에 해당 월 실제·예측이 모두 주어졌는지 확인. 한 달씩 순서대로 전개한다.","src":"기출 2022-19, 2025-27"},{"t":"예(2021-20): 55,400+0.6×(56,900−55,400)=56,300.","src":"기출 2021-20"},{"t":"예(2022-19): 7월 예측 50,000+0.4×(48,000−50,000)=49,200. 8월 49,200+0.4×(52,000−49,200)=50,320.","src":"기출 2022-19"},{"t":"예(2024-20): 110,000+0.2×(100,000−110,000)=108,000.","src":"기출 2024-20"},{"t":"예(2025-27): 7월 94,000+0.3×4,000=95,200. 8월 95,200+0.3×(92,000−95,200)=94,240.","src":"기출 2025-27"},{"t":"예(2026-23): 9월 5,000+0.2×(5,500−5,000)=5,100. 직전 달 실제(7월)는 쓰지 않는다.","src":"기출 2026-23"},{"t":"단순이동평균(n=3) = 최근 3기 합 ÷ 3. 예(2021-22): (36+34+37)÷3=35.7.","src":"기출 2021-22"},{"t":"가중이동평균 = Σ(가중치×실적). 예(2021-22): 0.5×37+0.3×34+0.2×36=35.9.","src":"기출 2021-22"},{"t":"예(2021-22) 지수평활: 39+0.4×(37−39)=38.2.","src":"기출 2021-22"}]}],"함정":[{"x":"델파이법(Delphi Method)은 원인과 결과관계를 가지는 두 요소의 과거 변화량에 대한 인과관계를 분석한 방법으로 정량적 수요예측방법에 해당한다.","o":"델파이법은 전문가 설문을 반복해 합의를 구하는 정성적 방법이다. 원인-결과 관계를 분석하는 것은 회귀분석 등 인과모형이다.","src":"기출 2022-21 / 기출 2021-29, 2026-24"},{"x":"지수평활법은 예측하고자 하는 기간의 직전 일정 기간의 시계열 평균값을 활용 하여 산출하는 방법이다.","o":"지수평활법은 실제수요와 직전 예측치에 가중치를 두어 새 예측치를 구한다. 직전 일정 기간 평균은 이동평균법이다.","src":"기출 2023-24 / 기출 2025-19"},{"x":"순환적(cyclical) 요인은 단기간에 발생하는 불규칙한 수요변화이다.","o":"순환적 요인은 수년 단위의 경기 변동에 따른 수요 변화이다. 단기간의 불규칙한 변화는 무작위(불규칙) 요인이다.","src":"기출 2024-18 / 보충"},{"x":"시계열분석법은 기존 제품과 관련된 과거의 자료를 분석하여 신제품의 미래 수요를 정성적으로 예측하는 방법이다.","o":"신제품의 미래 수요를 유사 제품의 과거 자료로 정성적으로 예측하는 것은 역사적 유추법이다. 시계열분석법은 정량적 방법이다.","src":"기출 2025-19 / 기출 2023-24, 2024-18"},{"x":"회귀분석법이 정성적 수요예측 기법이다.","o":"회귀분석은 정량적(인과모형) 기법이다.","src":"기출 2021-29, 2026-24"},{"x":"이동평균법·선형 회귀분석이 정성적 예측방법이다(2026-24 ㄱ, ㄹ).","o":"둘 다 정량적 방법이다.","src":"기출 2026-24"}]},"#12":{"묶음":[{"머리":"EOQ 모형의 가정","줄":[{"t":"수요는 확정적이고 일정하다. 조달기간(리드타임)이 일정하다.","src":"기출 2022-17, 2024-25, 2025-17, 2026-19"},{"t":"주문량은 전량 일시에 입고된다. 단일 품목이다.","src":"기출 2022-17, 2024-25, 2025-17, 2026-19"},{"t":"재고부족(품절)을 허용하지 않는다. 미납주문도 없다.","src":"기출 2025-17, 2026-19"},{"t":"주문비용과 단가는 주문량과 무관하게 일정하다. 수량할인이 없다.","src":"기출 2022-17, 2024-25"},{"t":"재고유지비용은 단위당 일정하고 평균재고량(주문량)에 비례한다. 주문량에 반비례하지 않는다.","src":"기출 2022-17, 2024-25, 2025-17, 2026-19"},{"t":"1회 주문비용은 주문량에 관계없이 일정하다.","src":"기출 2025-17"}]},{"머리":"공식","줄":[{"t":"EOQ = √(2 × 연간수요량 D × 1회 주문비용 S ÷ 단위당 연간 재고유지비용 H).","src":"기출 2021-21, 2022-20, 2023-19, 2025-25, 2026-22"},{"t":"EOQ에서 연간 주문비용(D/Q×S)과 연간 재고유지비용(Q/2×H)이 같고, 총재고비용은 둘의 합이다.","src":"기출 2022-20"},{"t":"연간 발주횟수 = D ÷ EOQ.","src":"기출 2022-20"},{"t":"재고유지비용 = 평균재고량 × 단가 × 재고유지비율. 단가 5%·재고 10,000개·5,000원이면 2,500,000원.","src":"기출 2023-22, 2025-24"},{"t":"EPQ = √(2DS ÷ (H × (1 − d/p))). d=일일 소비량, p=일일 생산량.","src":"기출 2024-22, 2026-20"},{"t":"재주문점 ROP = 리드타임 중 평균수요(일평균수요×리드타임) + 안전재고.","src":"기출 2022-22, 2025-23"},{"t":"안전재고 = Z × 일수요 표준편차 × √리드타임.","src":"기출 2022-22, 2026-21"},{"t":"EOQ가 알려져 있을 때 1회 주문비용 S = EOQ² × H ÷ (2D).","src":"기출 2026-22"}]},{"머리":"계산 풀이","줄":[{"t":"예(2021-21): D 4,000→6,400(60%↑), H 75→60(20%↓). EOQ는 √(1.6÷0.8)=√2≈1.414배, 약 41% 증가.","src":"기출 2021-21"},{"t":"예(2022-20): D 90,000, H=80,000×25%=20,000, S 160,000 → EOQ=1,200. 총재고비용=600×20,000+75×160,000=24,000,000원. 발주 75회.","src":"기출 2022-20"},{"t":"예(2022-22): 일수요 14,000÷350=40, 리드타임 9일 → 360. 안전재고 1.282×20×√9≈77. ROP=437.","src":"기출 2022-22"},{"t":"예(2023-19): √(2×20,000×80,000÷(4,000×0.2))=2,000개.","src":"기출 2023-19"},{"t":"예(2024-22): D 2,700, S 400,000, H 13,500, d=9, p=12 → √(2×2,700×400,000÷(13,500×0.25))=800톤.","src":"기출 2024-22"},{"t":"예(2025-23): 200×3+400=1,000개.","src":"기출 2025-23"},{"t":"예(2025-25): √(2×1,200×60,000÷900)=400개.","src":"기출 2025-25"},{"t":"예(2026-20): √(2×3,600×100,000÷(36,000×0.5))=200개.","src":"기출 2026-20"},{"t":"예(2026-21): 1.5×250×√16=1,500개.","src":"기출 2026-21"},{"t":"예(2026-22): 4,000²×500÷(2×100,000)=40,000원.","src":"기출 2026-22"}]},{"머리":"발주 시스템","줄":[{"t":"정량발주시스템(Q시스템, 연속점검시스템): 재고수준을 연속적으로 검토하고 주문량이 일정하다.","src":"기출 2024-24, 2025-18, 2026-25"},{"t":"정기발주시스템(P시스템): 재고수준 파악과 발주를 정기적으로 하고, 목표수준에 도달하도록 발주량을 정한다. 정량발주보다 안전재고가 많다.","src":"기출 2024-24 / 보충"},{"t":"기준재고시스템(s-S): 보유재고가 s보다 적어지면 최대재고량 S에 도달하도록 발주량을 정한다.","src":"기출 2024-24"},{"t":"확률적 정량발주법: 주문량이 일정하고 Q시스템이며 수요가 불확실할 때 쓰고 연속실사로 재고를 조사한다.","src":"기출 2026-25"},{"t":"재주문점 기법: 정량발주법, Two-Bin법, 기준재고법, 정기발주법. 델파이법은 수요예측 기법이다.","src":"기출 2023-23"}]}],"함정":[{"x":"주문량이 커질수록 할인율이 높아지기 때문에 가능한 많은 주문량을 설정하는 것이 유리하다.","o":"EOQ 모형은 수량할인이 없다고 가정한다. 단가·주문비용은 주문량과 무관하게 일정하다.","src":"기출 2022-17 / 기출 2024-25"},{"x":"재고유지비용은 평균재고량에 반비례한다.","o":"재고유지비용은 평균재고량에 비례한다.","src":"기출 2022-17 / 기출 2024-25, 2025-17"},{"x":"재고부족에 대응하기 위한 안전재고가 필요하다.","o":"EOQ 모형은 재고부족을 허용하지 않으므로 안전재고가 필요 없다.","src":"기출 2022-17 / 기출 2025-17, 2026-19"},{"x":"수요가 불확실하기 때문에 주문량과 주문간격이 달라진다.","o":"EOQ 모형은 수요가 확정적이고 일정하므로 주문량과 주문간격이 일정하다.","src":"기출 2022-17 / 기출 2026-19"},{"x":"정기발주시스템: 통상 정량발주시스템에 비하여 적은 안전재고량을 갖는다.","o":"정기발주시스템은 정량발주시스템보다 안전재고량이 많다(점검 사이 기간까지 대비해야 하므로).","src":"기출 2024-24 / 보충"},{"x":"EOQ 모형에서 재고부족에 대응하는 안전재고가 필요하다.","o":"재고부족을 허용하지 않으므로 안전재고를 두지 않는다.","src":"기출 2022-17"},{"x":"정기발주시스템은 통상 정량발주시스템보다 적은 안전재고량을 갖는다.","o":"정기발주가 안전재고를 더 많이 갖는다.","src":"기출 2024-24 / 보충"},{"x":"정기발주법은 연속적으로 재고수준을 점검하는 연속점검시스템이다.","o":"연속점검시스템은 정량발주법이다.","src":"기출 2025-18"},{"x":"EOQ 모형의 가정: 재고유지비용은 주문량에 반비례한다(2024-25).","o":"주문량에 비례한다.","src":"기출 2024-25"},{"x":"EOQ 모형의 가정: 미납주문은 다음 입고 시 우선 처리한다(2026-19).","o":"재고부족을 허용하지 않아 미납주문 자체가 없다.","src":"기출 2026-19"},{"x":"EOQ 전제: 주문량이 다량일 경우 할인율을 적용한다. 1회 주문당 비용은 주문량에 비례해 증가한다(2025-17 ㄷ, ㅁ).","o":"수량할인이 없고, 1회 주문비용은 일정하다.","src":"기출 2025-17"},{"x":"델파이법은 재주문점의 주문관리 기법이다.","o":"델파이법은 수요예측(정성적) 기법이다. 재주문점 기법은 정량발주법, Two-Bin법, 기준재고법, 정기발주법이다.","src":"기출 2023-23"}]},"#13":{"묶음":[{"머리":"재고관리의 목적·장점·보유 이유","줄":[{"t":"재고관리는 제품·반제품·원재료·상품 등을 합리적·경제적으로 유지하기 위한 활동이다.","src":"기출 2022-23"},{"t":"재고관리 장점: 실제 재고량 파악, 불확실성 대비, 가용 제품 확대로 고객서비스 달성, 수요·공급 변동성 대응. 상품 공급의 지연은 장점이 아니다.","src":"기출 2021-25, 2022-23"},{"t":"재고관리 목표: 서비스율 증대, 백오더율 감소, 재고회전율 증대, 손상율 감소, 보관비용 감소.","src":"기출 2024-23"},{"t":"재고 보유 이유: 원재료 부족으로 인한 생산중단 방지, 작업준비 시간·비용이 클 때 생산계획의 유연성 확보, 미래 위험 회피, 계절 집중 출하품의 판매기회 확보.","src":"기출 2023-21"},{"t":"재고를 필요 이상 보유하면 과도한 재고비용이 발생한다.","src":"기출 2022-23"},{"t":"재고는 공급사슬의 수요·공급 변동과 불확실성에 대한 완충 역할을 한다.","src":"기출 2022-23"}]},{"머리":"재고 지표","줄":[{"t":"서비스율 = 납기 내 납품량 ÷ 전체 수주량.","src":"기출 2023-18, 2025-18"},{"t":"백오더율 = 납기 내 결품량 ÷ 전체 수주량.","src":"기출 2023-18, 2025-18"},{"t":"재고회전율 = 연간 매출액 ÷ 평균재고액. 예(2025-22): 300억÷60억=5.","src":"기출 2023-18, 2025-22"},{"t":"재고회전기간 = 수요대상 기간 ÷ 재고회전율.","src":"기출 2023-18"},{"t":"평균재고액 = (기초재고액 + 기말재고액) ÷ 2.","src":"기출 2023-18 / 보충"}]},{"머리":"재고의 종류","줄":[{"t":"주기재고(Cycle Inventory): 연간 주문횟수를 줄여 주문비용을 절감하려는 로트 단위 조달에서 생긴다.","src":"기출 2022-23, 2025-18"},{"t":"안전재고(Safety Stock): 수요·공급의 불확실성에 대비한다. 재고유지비 부담을 키우므로 적정 수준으로 관리한다.","src":"기출 2022-23, 2025-18"},{"t":"공급자관리재고(VMI): 공급사슬에서 생산자(공급자)가 납품 대상업체의 재고량을 유지·관리한다.","src":"기출 2021-24, 2025-21"},{"t":"재공품(WIP): 제조부 내 공정관리 대상인 가공 중 자재. 보통 생산현장에 놓여 있다.","src":"기출 2025-21"},{"t":"예비재고(Anticipation Stock): 계절적 수요 증가를 예상하거나 계획적 공장가동 중단에 대비해 사전에 준비하는 재고.","src":"기출 2025-21"},{"t":"운송중재고(Pipeline Stock), 완충재고(Buffer Stock), 로트사이즈 재고(Lot-size Stock)도 재고 유형이다.","src":"기출 2025-21"}]},{"머리":"채찍효과 해소 방안","줄":[{"t":"공급사슬 주체 간 실시간 정보공유, VMI, EDLP, CPFR, 리드타임 단축.","src":"기출 2021-24"},{"t":"리드타임을 길게 설정하는 것은 해소 방안이 아니다.","src":"기출 2021-24"}]},{"머리":"JIT (Just In Time)","줄":[{"t":"JIT는 불필요한 부품·재공품 재고를 없애는 것을 목표로 한다. 재고수준을 낮추고 불량품을 최소화한다.","src":"기출 2021-27, 2026-26"},{"t":"효과적인 Pull(끌어당기기) 시스템을 구현한다. 칸반시스템을 주로 활용한다.","src":"기출 2022-24, 2026-26"},{"t":"반복적 생산에 적합하다. 제조준비시간과 리드타임을 단축한다. 로트 크기를 줄인다.","src":"기출 2021-27, 2022-24, 2025-20"},{"t":"공급업체의 안정적 자재공급과 엄격한 품질관리, 공급업체와 생산업체의 상호협력이 있어야 효과가 난다.","src":"기출 2022-24"},{"t":"필요한 시기·양만큼 자재를 조달해 수요변화에 유연하게 대처한다.","src":"기출 2025-20"},{"t":"다기능공 양성이 필요하다(단일 기능공이 아니다).","src":"기출 2021-27 / 보충"}]}],"함정":[{"x":"안전재고는 재고를 품목별로 일정한 로트(Lot) 단위로 조달하기 때문에 발생한다.","o":"로트 단위 조달 때문에 생기는 재고는 주기재고이다. 안전재고는 수요·공급의 불확실성에 대비한 재고이다.","src":"기출 2022-23 / 기출 2025-18, 2022-23"},{"x":"평균재고액은 기말재고액에서 기초재고액을 뺀 값이다.","o":"평균재고액 = (기초재고액 + 기말재고액) ÷ 2.","src":"기출 2023-18 / 보충"},{"x":"기술력 향상 및 생산공정의 자동화 도입 촉진을 위해 재고를 보유한다.","o":"재고 보유 이유는 수요·공급 불확실성 대응, 로트 구매, 계절 수요 등이다. 기술력 향상·자동화 촉진은 재고 보유 목적이 아니다.","src":"기출 2023-21 / 기출 2023-21"},{"x":"정기발주법은 연속적으로 재고수준을 점검하므로 연속점검시스템(Continuous Review System)이라 한다.","o":"연속적으로 재고수준을 점검하는 연속점검시스템은 정량발주법이다. 정기발주법은 정기적으로 점검한다.","src":"기출 2025-18 / 기출 2024-24"},{"x":"리드타임을 길게 설정(채찍효과 해소 방안)","o":"리드타임을 단축해야 채찍효과가 줄어든다.","src":"기출 2021-24"},{"x":"상품 공급의 지연(delay)이 재고관리의 장점이다.","o":"장점이 아니다.","src":"기출 2021-25"},{"x":"백오더(back order)율 증대(재고관리의 목표)","o":"백오더율은 낮추는 것이 목표이다.","src":"기출 2024-23"},{"x":"JIT: 한 작업자에게 업무가 할당되는 단일 기능공 양성이 필수적이다.","o":"다기능공이 필요하다.","src":"기출 2021-27 / 보충"},{"x":"JIT: 효과적인 Push 시스템을 구현할 수 있다.","o":"JIT는 Pull 시스템이다.","src":"기출 2021-27, 2025-20, 2026-26"},{"x":"JIT: 비반복적 생산시스템에 적합하다.","o":"반복적 생산에 적합하다.","src":"기출 2021-27, 2022-24"},{"x":"JIT: 제조 준비 시간이 길어진다.","o":"제조준비시간이 짧아진다.","src":"기출 2021-27"},{"x":"JIT: 충분한 안전재고를 확보하므로 공급업체와 상호협력 없이도 운영 가능(2022-24 선지 5)","o":"공급업체의 안정적 공급과 협력이 필수이다. 안전재고를 최소화한다.","src":"기출 2022-24"},{"x":"JIT: 다품종 소량생산과 소량다빈도 배송으로 운송비가 절감된다(2025-20 ㄱ).","o":"소량다빈도 배송은 운송비를 키운다.","src":"기출 2025-20 / 보충(추정)"},{"x":"JIT: 자재를 거점창고에 통합 보관하므로 재고비용 절감과 취급이 용이(2025-20 ㄷ).","o":"JIT는 거점창고 통합 보관이 아니라 필요한 시기에 소량 조달한다.","src":"기출 2025-20 / 보충(추정)"}]},"#14":{"묶음":[{"머리":"하역의 의의·구성","줄":[{"t":"하역은 운송 및 보관에 수반해 생산에서 소비에 이르는 전 유통과정에서 행해진다.","src":"기출 2023-25"},{"t":"하역은 적하·운반·적재·반출·분류·정돈으로 구성된다.","src":"기출 2021-40, 2023-25, 2024-29"},{"t":"하역은 시간·장소 효용을 창출한다. 형태효용은 창출하지 않는다.","src":"기출 2021-40, 2023-25"},{"t":"하역 요소에는 쌓기, 내리기, 반출, 꺼내기, 운반이 든다. 통관은 하역 구성 요소가 아니다.","src":"기출 2024-29"},{"t":"물류센터 내 물품의 짧은 거리 이동(운반)도 하역 범위에 든다. 정돈·분류도 포함한다.","src":"기출 2022-26, 2024-26"},{"t":"하역작업 장소별 분류: 사내하역, 항만하역, 항공하역. 제조업체 사내하역은 조달·생산 과정의 운반과 하역을 포함한다.","src":"기출 2022-28, 2023-28"},{"t":"하역시스템 기계화·자동화로 작업환경이 개선되고 에너지·자원이 절약된다. 전자상거래 시대에 중요성이 커진다.","src":"기출 2022-28, 2023-28, 2024-26"},{"t":"하역의 기계화가 필요한 화물: 액체·분립체, 많은 인적 노력이 요구되는 화물, 상하차가 곤란한 높낮이의 작업장, 인력으로 시간을 맞추기 어려운 화물(4개 모두).","src":"기출 2022-31"}]},{"머리":"하역합리화 원칙 전체","줄":[{"t":"운반 활성화의 원칙: 화물의 이동 용이성(운반활성지수)을 최대화한다.","src":"기출 2022-25, 2023-26, 2025-28"},{"t":"하역 경제성의 원칙: 불필요한 하역작업을 생략해 작업능률을 높이고 파손·분실을 줄인다.","src":"기출 2022-25, 2023-26"},{"t":"거리(시간) 최소화의 원칙: 화물의 이동거리(톤·킬로)를 최소화한다.","src":"기출 2021-39, 2022-25, 2023-26, 2025-28"},{"t":"화물 단위화의 원칙: 화물을 일정한 중량 또는 용적으로 단위화한다.","src":"기출 2023-26"},{"t":"시스템화의 원칙, 인터페이스의 원칙도 하역 원칙으로 출제됐다. 동일성 원칙은 하역의 원칙이 아니다.","src":"기출 2022-25, 2024-28"}]},{"머리":"운반활성지수","줄":[{"t":"0: 화물이 바닥에 놓인 상태. 1: 상자 안에 넣은 상태. 2: 파렛트 위에 놓인 상태. 3: 대차에 실은 상태. 4: 컨베이어 위에 놓인 상태.","src":"기출 2022-27, 2024-27, 2026-29"},{"t":"활성지수가 가장 높은 상태는 컨베이어 위(4)이다.","src":"기출 2026-29"},{"t":"예(2024-27): 컨베이어 4 + 바닥 0 + 대차 3 + 상자 1 = 8.","src":"기출 2024-27"}]},{"머리":"하역 용어 전체","줄":[{"t":"더니지(Dunnage): 화물이 손상·파손되지 않도록 밑바닥이나 틈 사이에 까는 물건. 깔거나 끼우는 작업.","src":"기출 2021-36, 2023-27, 2025-30"},{"t":"래싱(Lashing): 운송기기에 실린 화물이 움직이지 않도록 줄로 고정하는 작업.","src":"기출 2021-36, 2023-27, 2025-30, 2026-28"},{"t":"스태킹(Stacking): 화물을 보관시설·장소에 규칙적으로 쌓는 작업.","src":"기출 2021-36, 2026-28"},{"t":"피킹(Picking): 보관 장소에서 화물을 꺼내는 작업.","src":"기출 2021-36, 2022-26, 2023-27"},{"t":"소팅(Sorting, 분류): 화물을 품종별·발송지별·고객별로 분류하는 작업.","src":"기출 2023-27"},{"t":"배닝(Vanning): 컨테이너에 화물을 싣는 작업. 디배닝(Devanning): 컨테이너에서 화물을 꺼내는 작업.","src":"기출 2022-26, 2025-30, 2026-28"},{"t":"운반: 창고 내부처럼 한정된 장소에서 화물을 이동하는 작업. 하역의 일부이다.","src":"기출 2022-26"},{"t":"적재: 물건을 보관시설로 옮겨 정해진 형태로 정해진 위치에 쌓는 작업.","src":"기출 2022-26"}]},{"머리":"하역 기계화·표준화","줄":[{"t":"물류합리화 관점에서 추진하고, 환경·안전을 고려한다.","src":"기출 2021-31, 2023-30"},{"t":"생산자·제조업자·물류업자 등 관련 당사자의 상호협력을 고려한다. 특정 화주 화물만을 대상으로 하지 않는다.","src":"기출 2021-31"},{"t":"운송·보관·포장·정보 등 물류활동 간의 호환성과 연계성을 고려하고 표준규격을 일관성 있게 만든다.","src":"기출 2023-30"},{"t":"유닛로드시스템에 맞는 하역·운반 장비의 표준화가 필요하다.","src":"기출 2023-30"}]}],"함정":[{"x":"배닝(Vanning): 파렛트에 화물을 쌓는 작업을 말한다.","o":"배닝(Vanning): 컨테이너에 화물을 싣는 작업. 파렛트에 쌓는 작업이 아니다.","src":"기출 2021-36 / 기출 2022-26, 2025-30"},{"x":"하역기기를 탄력적으로 운영하여야 한다.","o":"하역기기는 탄력적으로 운영하는 것이 바람직하다는 설명(옳은 서술). 이 문항은 발문 미확인.","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"불필요한 물품의 취급을 최소화하여야 한다.","o":"불필요한 물품 취급을 최소화하는 것은 하역합리화 원칙에 맞는 서술(발문 미확인).","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"하역작업을 표준화하여 효율성을 추구하여야 한다.","o":"하역작업을 표준화하여 효율성을 추구하는 것은 하역합리화 원칙에 맞는 서술(발문 미확인).","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"복잡한 시설과 하역체계를 단순화하여야 한다.","o":"복잡한 시설과 하역체계를 단순화하는 것은 하역합리화 원칙에 맞는 서술(발문 미확인).","src":"기출 2021-39 / 출제 오답(발문 미확인, 검수 필요)"},{"x":"제품에 대한 형태효용을 창출한다.","o":"하역은 시간·장소 효용을 창출한다. 형태효용은 생산의 몫이다.","src":"기출 2021-40 / 기출 2023-25 / 보충"},{"x":"운반활성화 지수를 최소화해야 한다.","o":"운반활성화 지수는 최대화를 지향한다.","src":"기출 2021-40 / 기출 2023-26, 2025-28"},{"x":"화물에 대한 제조공정과 검사공정을 포함한다.","o":"하역은 적하·운반·적재·반출·분류로 구성된다. 제조공정과 검사공정은 포함하지 않는다.","src":"기출 2021-40 / 기출 2021-40, 2023-25"},{"x":"기계화와 자동화를 통한 하역생산성 향상이 어렵다.","o":"기계화와 자동화로 하역생산성을 높일 수 있다.","src":"기출 2021-40 / 기출 2022-28, 2023-25"},{"x":"하역시스템의 도입 목적은 범용성과 융통성을 지양하는데 있다.","o":"하역시스템은 범용성과 융통성을 갖추는 것을 목적으로 한다.","src":"기출 2022-28 / 보충(추정)"},{"x":"시간, 장소 및 형태 효용을 창출한다.","o":"하역은 시간·장소 효용을 창출한다. 형태효용은 생산공정의 효용이다.","src":"기출 2023-25 / 보충"},{"x":"운반활성지수를 최소화한다.","o":"운반활성지수는 최대화를 지향한다.","src":"기출 2023-26 / 기출 2021-40, 2025-28"},{"x":"필요한 원재료ㆍ반제품ㆍ제품 등의 최적 보유량을 계획하고 조직하고 통제하는 기능을 한다.","o":"필요한 원재료·반제품·제품의 최적 보유량을 계획·통제하는 것은 재고관리의 기능이다.","src":"기출 2023-28 / 기출 2023-28"},{"x":"생산의 마지막 단계로 치수, 강도, 재질, 기법 등의 표준화로 구성된다.","o":"하역의 표준화는 생산의 마지막 단계가 아니라 운송·보관·포장·정보 등 물류 전체의 호환성을 위해 치수·강도·재질·기법을 통일하는 것이다.","src":"기출 2023-30 / 기출 2023-30"},{"x":"물류센터 내에서 물품의 짧은 거리 이동은 하역의 범위에 포함되지 않는다.","o":"물류센터 내에서 물품을 짧은 거리로 옮기는 것(운반)도 하역의 범위에 포함된다.","src":"기출 2024-26 / 기출 2022-26, 2024-29"},{"x":"하역은 운송 수단에 실려 있는 물품을 꺼내는 일만을 의미하며, 정돈이나 분류 는 하역의 범위에 포함되지 않는다.","o":"하역은 적하·운반·적재·반출·분류·정돈을 모두 포함한다.","src":"기출 2024-26 / 기출 2023-25, 2024-29"},{"x":"하역작업의 생산성을 향상시키기 위해 인력 하역 비중이 늘어나는 추세이다.","o":"하역작업은 기계화·자동화로 생산성을 높이는 추세이며 인력 하역 비중은 줄어든다.","src":"기출 2024-26 / 기출 2023-28"},{"x":"하역작업의 혁신을 위해 물류센터 장비의 기계화와 무인화를 늦게 도입해야 한다.","o":"물류센터 장비의 기계화·무인화는 늦추지 않고 도입한다(전자상거래 시대에 하역 중요성 증가).","src":"기출 2024-26 / 기출 2024-26"},{"x":"경제성 원칙: 하역작업의 횟수를 증가시켜 비용을 최대화한다.","o":"경제성 원칙: 불필요한 하역작업을 줄여 비용을 최소화한다.","src":"기출 2025-28 / 기출 2023-26"},{"x":"운반활성화 원칙: 운반활성화 지수를 최소화한다.","o":"운반활성화 원칙: 운반활성지수를 최대화한다.","src":"기출 2025-28 / 기출 2023-26"},{"x":"화물 단위화의 원칙: 다품종 소량운송을 위해 화물을 개별화하여 하역한다.","o":"화물 단위화의 원칙: 화물을 파렛트·컨테이너 등으로 묶어 일정 중량·용적으로 단위화한다.","src":"기출 2025-28 / 기출 2023-26"},{"x":"화물유동화 원칙: 화물의 손상, 분실 등을 최소화하기 위하여 하역공정을 멈추고 불량 검사를 한다.","o":"화물유동화 원칙은 하역공정을 멈추지 않고 흐름을 유지하는 방향이다. 하역공정을 멈추고 불량 검사를 하는 것은 아니다.","src":"기출 2025-28 / 보충(추정)"},{"x":"하역은 시간·장소 및 형태 효용을 창출한다.","o":"시간·장소 효용을 창출한다. 형태효용은 아니다.","src":"기출 2023-25"},{"x":"특정 화주의 화물을 대상으로 추진(하역의 기계화·표준화 고려사항)","o":"특정 화주가 아니라 물류합리화 관점으로 추진한다.","src":"기출 2021-31"},{"x":"하역의 원칙: 동일성 원칙","o":"하역의 원칙이 아니다(운반활성화, 경제성, 이동거리 최소화, 단위화 등).","src":"기출 2024-28"},{"x":"스태킹(Stacking): 화물이 손상되지 않도록 밑바닥이나 틈 사이에 물건을 깔거나 끼우는 작업(2023-27, 2025-30)","o":"그 설명은 더니지이다. 스태킹은 규칙적으로 쌓는 작업이다.","src":"기출 2023-27, 2025-30"},{"x":"디배닝(Devanning): 컨테이너에 화물을 싣는 작업(2025-30)","o":"컨테이너에서 화물을 꺼내는 작업이다.","src":"기출 2025-30"},{"x":"피킹(Picking): 화물을 유형별·고객별·도착지별로 분류하는 작업(2025-30)","o":"피킹은 보관 장소에서 화물을 꺼내는 작업이다. 분류는 소팅이다.","src":"기출 2025-30"},{"x":"분류(Sorting): 출하 화물을 수송기기에 바로 실을 수 있게 정돈하는 작업(2025-30)","o":"그 설명은 정돈이다. 분류는 품종·고객·도착지별로 나누는 작업이다.","src":"기출 2025-30"},{"x":"하역 구성 요소에 통관이 포함된다(2024-29 ㅂ).","o":"통관은 하역 구성 요소가 아니다.","src":"기출 2024-29"}]},"#15":{"묶음":[{"머리":"하역기기 선정","줄":[{"t":"선정 기준: 에너지 효율성, 안전성, 작업량과 작업 특성, 취급 품목의 종류, 경제성.","src":"기출 2021-33, 2025-29"},{"t":"사내하역 선정 기준에는 취급화물의 중량·종류, 건물구조와 시설배치도 든다.","src":"기출 2025-29"},{"t":"화물의 원산지·목적지는 선정 기준이 아니다.","src":"기출 2021-33, 2025-29"}]},{"머리":"지게차(Forklift) 종류","줄":[{"t":"카운터 밸런스형: 포크와 마스트를 전방에 장착하고 후방에 웨이트를 둔다.","src":"기출 2024-30"},{"t":"사이드 포크형: 차체 측면에 포크와 마스트가 장착된다.","src":"기출 2022-30, 2024-30"},{"t":"스트래들형: 차체 전방에 아웃리거를 설치하고 그 사이에 포크를 두어 안정성을 높인다.","src":"기출 2022-30"},{"t":"3방향 작동형: 포크와 캐리지가 회전해 진행방향 변경 없이 작업한다.","src":"기출 2022-30"},{"t":"워키(Walkie)형: 작업자가 걸어서 조작하는 소형 지게차.","src":"기출 2022-30 / 보충"},{"t":"전동식은 실내작업에, 디젤엔진식은 배기가스·소음 때문에 실외에 맞는다.","src":"기출 2022-30 / 보충"}]},{"머리":"컨베이어·무인운반","줄":[{"t":"벨트 컨베이어: 연속 이동하는 벨트로 화물을 운반한다.","src":"기출 2024-30"},{"t":"롤러·휠 컨베이어: 로울러 또는 휠을 배열해 화물을 운반한다. 트롤리 컨베이어는 천장 레일에 매달아 이송한다.","src":"기출 2024-30 / 보충"},{"t":"AGV: 지정된 장소까지 자동 주행하는 장비.","src":"기출 2024-30"}]},{"머리":"컨테이너·벌크 하역기기","줄":[{"t":"언로우더(Unloader): 철광석·석탄·석회석 같은 벌크 화물을 하역한다.","src":"기출 2021-38"},{"t":"호퍼(Hopper): 원료·연료·화물을 컨베이어나 기계로 이송하는 깔때기 모양 장비. 컨테이너터미널 장비가 아니다.","src":"기출 2022-37, 2023-29"},{"t":"톱 핸들러(Top Handler): 공(empty) 컨테이너를 적치한다.","src":"기출 2021-38"},{"t":"트랜스퍼 크레인(Transfer Crane): 컨테이너를 적재하거나 다른 장소로 이송·반출한다.","src":"기출 2021-38"},{"t":"천정 크레인(Overhead Travelling Crane): 크레인 본체가 천장을 주행하며 화물을 상하로 들어 올리고 수평 이동한다.","src":"기출 2021-38"},{"t":"리치 스태커(Reach Stacker): 철도터미널 화차의 컨테이너 상·하차, 스프레더로 운반·적재, 긴 붐으로 풀 컨테이너를 CY 내에서 이동한다.","src":"기출 2025-36"},{"t":"스트래들 캐리어: 컨테이너를 양다리 사이에 끼워 운반한다.","src":"기출 2021-12"},{"t":"로딩 암(Loading Arm): 본선과 터미널 간 액체화물 이송에 연결하는 육상 터미널 측 장비.","src":"기출 2023-29 / 보충"},{"t":"그라브 버켓(Grab Bucket)은 컨테이너터미널 장비가 아니다(벌크용).","src":"기출 2026-38"}]},{"머리":"항공하역","줄":[{"t":"항공화물 탑재방식: 살화물, 파렛트, 컨테이너 탑재방식.","src":"기출 2026-36"},{"t":"리프트 로더(Lift Loader): 파렛트를 항공기 적재공간 바닥 높이까지 들어 올려 탑재한다.","src":"기출 2021-19, 2026-36"},{"t":"돌리(Dolly): 파렛트 운반용 차대. 자체 기동력이 없고 터그 카(Tug Car)에 연결해 쓴다.","src":"기출 2021-19"},{"t":"트랜스포터(Transporter): 항공기에서 내린 ULD를 터미널까지 수평 이동한다.","src":"기출 2021-19, 2026-36"},{"t":"터그 카, 이글루(igloo), 파렛트 스케일도 항공하역 장비다.","src":"기출 2024-39, 2025-35, 2026-36"},{"t":"항공하역 장비 해당: 이글루, 트랜스포터, 돌리, 터그 카. 리치스태커·탑 핸들러·스트래들 캐리어·로딩 암은 아니다.","src":"기출 2024-39, 2025-35"},{"t":"소터(Sorter): 비교적 소형 화물을 행선지별·인도지별로 구분하는 장치. 통상 컨베이어와 제어장치로 구성한다.","src":"기출 2021-19"}]},{"머리":"철도하역 방식","줄":[{"t":"TOFC(Trailer on Flat Car): 컨테이너를 실은 트레일러를 철도화차 위에 적재해 운송한다.","src":"기출 2023-32"},{"t":"COFC(Container on Flat Car): 화차 위에 컨테이너만 적재한다.","src":"기출 2023-32"},{"t":"피기백(Piggy Back): 화물열차 대차 위에 트레일러나 트럭을 컨테이너 등과 함께 싣는다.","src":"기출 2023-32"},{"t":"캥거루(Kangaroo): 화차에 트레일러 바퀴가 들어갈 홈이 있어 적재높이가 낮다.","src":"기출 2023-32"},{"t":"트럭이 화물열차에 직각으로 후진해 무개화차에 컨테이너를 바로 싣는 방식은 플렉시밴(Flexi-Van)이다. 프레이트 라이너는 컨테이너 전용 직행 열차이다.","src":"기출 2023-32 / 보충"}]}],"함정":[{"x":"컨투어게이지(Contour Gauge): 파렛트에 적재가 끝난 후 적재된 파렛트의 무게를 계량하기 위하여 트레일러에 조립시켜 놓은 장치이다.","o":"컨투어게이지(Contour Gauge): 적재한 화물의 외곽 윤곽이 항공기 적재공간에 맞는지 재는 장치이다. 무게 계량 장치가 아니다.","src":"기출 2021-19 / 보충(추정)"},{"x":"스트래들 캐리어(Straddle Carrier): 부두의 안벽에 설치되어 선박에 컨테이너를 선적하거나 하역하는데 사용된다.","o":"스트래들 캐리어: 컨테이너를 양다리 사이에 끼워 야드에서 운반·적재한다. 안벽에서 선적·하역하는 장비는 컨테이너크레인(안벽크레인)이다.","src":"기출 2021-38 / 기출 2021-12, 2023-29 / 보충"},{"x":"스트래들(Straddle)형은 전방이 아닌 차체의 측면에 포크와 마스트가 장착된 지 게차이다.","o":"스트래들형 지게차: 차체 전방의 아웃리거 사이에 포크를 두어 안정성을 높인다. 측면에 포크와 마스트가 있는 것은 사이드포크형이다.","src":"기출 2022-30 / 기출 2022-30, 2024-30"},{"x":"디젤엔진식은 유해 배기가스와 소음이 적어 실내작업에 적합한 환경친화형 장비 이다.","o":"디젤엔진식은 배기가스와 소음이 커서 실내작업에는 전동식이 적합하다.","src":"기출 2022-30 / 보충"},{"x":"워키(Walkie)형은 스프레더를 장착하고 항만 컨테이너 야드 등 주로 넓은 공간 에서 사용된다.","o":"워키(Walkie)형은 작업자가 걸어서 조작하는 소형 지게차이다. 스프레더로 컨테이너를 다루는 것은 컨테이너용 장비이다.","src":"기출 2022-30 / 보충"},{"x":"사이드 포크형은 차체전방에 아웃리거를 설치하고 그 사이에 포크를 위치시켜 안정성을 향상시킨 지게차이다.","o":"사이드포크형: 차체 측면에 포크와 마스트가 장착된 지게차이다. 전방 아웃리거 사이에 포크를 두는 것은 스트래들형이다.","src":"기출 2022-30 / 기출 2024-30, 2022-30"},{"x":"트롤리 컨베이어는 로울러 또는 휠을 배열하여 화물을 운반하는 컨베이어이다.","o":"로울러 또는 휠을 배열해 화물을 운반하는 것은 롤러·휠 컨베이어이다. 트롤리 컨베이어는 천장 레일에 매단 트롤리로 이송한다.","src":"기출 2024-30 / 보충"},{"x":"항공컨테이너는 해상컨테이너와 호환이 가능하다.","o":"항공컨테이너는 해상컨테이너와 호환되지 않는다.","src":"기출 2026-36 / 기출 2026-36"},{"x":"하역물품의 원산지(하역기기 선정 기준으로)","o":"원산지는 선정 기준이 아니다.","src":"기출 2021-33"},{"x":"취급화물의 원산지와 목적지(사내하역 하역기기 선정 기준)","o":"선정 기준이 아니다.","src":"기출 2025-29"},{"x":"Freight Liner 방식: 트럭이 화물열차에 직각으로 후진하여 무개화차에 컨테이너를 바로 실어 운송","o":"그 설명은 플렉시밴 방식이다.","src":"기출 2023-32 / 보충"},{"x":"탑 핸들러: 본선과 터미널 간 액체화물 이송 시 연결되는 육상 터미널 측 장비(2023-29)","o":"그 설명은 로딩 암이다. 탑 핸들러는 공 컨테이너 적치 장비이다.","src":"기출 2023-29 / 보충"},{"x":"로딩 암: 부두에서 본선으로 석탄·광석 벌크화물을 선적하는 장비(2023-29)","o":"벌크 선적 장비가 아니다. 로딩 암은 액체화물 이송 연결 장비이다.","src":"기출 2023-29 / 보충"},{"x":"돌리: 해상 컨테이너를 적재하거나 이송·반출하는 장비(2023-29)","o":"그 설명은 트랜스퍼 크레인이다. 돌리는 파렛트 운반 차대이다.","src":"기출 2021-19, 2021-38"},{"x":"호퍼(Hopper)가 컨테이너터미널 하역기기이다(2022-37).","o":"호퍼는 컨테이너터미널 장비가 아니다.","src":"기출 2022-37"},{"x":"그라브 버켓이 컨테이너터미널 장비이다(2026-38).","o":"컨테이너터미널 장비가 아니다.","src":"기출 2026-38"},{"x":"리치스태커·탑 핸들러·스트래들 캐리어·로딩 암이 항공하역 장비이다.","o":"항공하역 장비가 아니다.","src":"기출 2024-39, 2025-35"}]},"#16":{"묶음":[{"머리":"컨테이너터미널 시설 전체","줄":[{"t":"선석(Berth): 컨테이너 선박이 접안하는 시설.","src":"기출 2021-18"},{"t":"에이프런(Apron): 안벽을 따라 폭 약 30~50m로 포장된 공간. 야드트럭이 하역작업을 하고 컨테이너크레인이 주행한다.","src":"기출 2021-18, 2024-38"},{"t":"마샬링 야드(Marshalling Yard): 선적·양하할 컨테이너를 임시 보관하는 공간. 대부분 에이프런에 인접한다.","src":"기출 2024-6"},{"t":"컨테이너 야드(CY): 컨테이너를 인도·인수·장치하는 장소.","src":"기출 2025-6 / 보충"},{"t":"CFS: LCL 화물의 적입(Stuffing)과 FCL 화물의 분리(Stripping) 작업을 하는 시설.","src":"기출 2021-18, 2025-6"},{"t":"컨트롤센터(Control Center): 본선 하역작업과 야드의 컨테이너 배치를 계획·통제·감독한다.","src":"기출 2021-18"},{"t":"게이트(Gate): 컨테이너터미널의 화물 출입통로.","src":"기출 2024-6"},{"t":"메인트넌스 숍(Maintenance Shop): 컨테이너 자체의 검사·보수·사용 전후 청소를 한다.","src":"기출 2024-6"},{"t":"위생검사소: 부패성 화물·음식물 같은 위생 위험 화물을 검사한다.","src":"기출 2024-6"},{"t":"잔교(Pier): 선박이 접안하는 구조물.","src":"기출 2024-38 / 보충"}]},{"머리":"안벽크레인 용어","줄":[{"t":"아웃리치(Outreach): 스프레더가 바다 측으로 최대로 나갔을 때 바다 측 레일중심에서 스프레더 중심까지의 거리.","src":"기출 2026-30"},{"t":"백리치(Backreach): 스프레더가 육지 측으로 최대로 나갔을 때 육지 측 레일중심에서 스프레더 중심까지의 거리.","src":"기출 2026-30"},{"t":"스프레더(Spreader): 컨테이너 크기에 맞추어 싱글·트윈 컨테이너를 하역하는 장치.","src":"기출 2026-30"},{"t":"계류장치: 크레인을 쓰지 않을 때 정지용 핀과 타이다운을 설치해 강풍·태풍으로부터 보호한다.","src":"기출 2026-30"}]},{"머리":"컨테이너터미널 운영방식·장비","줄":[{"t":"새시(Chassis) 방식: 컨테이너를 새시 위에 적재한 상태로 필요할 때 이송한다.","src":"기출 2021-12"},{"t":"스트래들 캐리어 방식: 컨테이너를 양다리 사이에 끼워 자유롭게 운반한다.","src":"기출 2021-12"},{"t":"트랜스테이너 방식: 트랜스퍼 크레인으로 컨테이너를 이동한다. 자동화가 어렵다는 설명은 틀렸다.","src":"기출 2021-12 / 보충(추정)"},{"t":"컨테이너터미널 장비: 리치 스태커, 야드 트랙터, 트랜스퍼 크레인, 탑 핸들러, 컨테이너 섀시, RMGC.","src":"기출 2022-37, 2026-38"}]},{"머리":"컨테이너 종류","줄":[{"t":"표준 컨테이너(드라이 컨테이너): 온도조절이 필요 없는 밀폐형.","src":"기출 2026-27"},{"t":"냉동 컨테이너(Reefer): 냉동·냉장 화물 수송용으로 냉동장치를 부착한다.","src":"기출 2026-27"},{"t":"오픈탑 컨테이너: 천장이 개방되는 컨테이너. 경량화물이 적합하다는 설명은 오답.","src":"기출 2026-27 / 보충(추정)"},{"t":"탱크 컨테이너: 액체 화물용. 지붕 맨홀로 넣고 밑면 호퍼로 배출하는 것은 벌크 컨테이너 설명.","src":"기출 2026-27 / 보충(추정)"}]},{"머리":"항만하역 작업방식","줄":[{"t":"LO-LO(Lift on-Lift off): 크레인으로 화물을 수직으로 들어 올려 싣고 내린다.","src":"기출 2023-31 / 보충"},{"t":"RO-RO(Roll on-Roll off): 선측·선미의 경사판을 거쳐 견인차로 수평 적재·양륙한다. 페리 선박에서 전통적으로 쓴다.","src":"기출 2023-31"},{"t":"RO-RO 방식으로 하역하는 선박: 자동차전용선, 카페리선(7종 중 2개).","src":"기출 2026-37"},{"t":"FO-FO(Float on-Float off), LASH(Lighter Aboard Ship)도 항만하역 방식이다.","src":"기출 2023-31"}]},{"머리":"항만운송사업법","줄":[{"t":"항만운송: 타인의 수요에 응하여 하는 행위로서 법 제2조 제1항 각 호에 해당하는 것.","src":"항만운송사업법 제2조"},{"t":"항만하역사업의 핵심 행위: 선박으로 운송된 화물을 화주 또는 선박운항업자의 위탁을 받아 항만에서 선박으로부터 인수하거나 화주에게 인도하는 행위.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"검수: 선적화물을 싣거나 내릴 때 화물의 개수를 계산하거나 인도·인수를 증명하는 일.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"감정: 선적화물·선박(부선 포함)에 관한 증명·조사·감정을 하는 일.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"검량: 선적화물을 싣거나 내릴 때 화물의 용적 또는 중량을 계산하거나 증명하는 일.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"t":"검수·감정·검량은 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"}]}],"함정":[{"x":"마샬링야드(Marshalling Yard): 컨테이너의 자체검사, 보수, 사용 전후 청소 등을 수행하는 공간이다.","o":"마샬링야드: 선적·양하할 컨테이너를 임시로 모아 두는 공간이다. 컨테이너 자체검사·보수·청소는 메인트넌스 숍의 일이다.","src":"기출 2021-18 / 기출 2024-6"},{"x":"ILS(Instrument Landing System)은 선박이 안전하게 접안할 수 있도록 유도하 는 시설로 평소에는 항만 하역장비를 보관하기도 한다.","o":"ILS는 항공기 계기착륙장치이다. 컨테이너터미널 시설이 아니다.","src":"기출 2024-6 / 보충(추정)"},{"x":"호이스트(Hoist)는 안벽크레인에 부착된 릴(Reel)로서 육상의 변전소에서 공급되는 전선을 감는 장치를 말한다.","o":"안벽크레인에 부착되어 전선을 감는 릴은 케이블 릴이다. 호이스트는 컨테이너를 들어 올리는 권상장치이다.","src":"기출 2026-30 / 보충(추정)"},{"x":"트랜스테이너 방식은 자동화가 어렵다(2021-12 ㄴ).","o":"트랜스퍼 크레인 방식은 자동화가 용이하다.","src":"기출 2021-12 / 보충(추정)"},{"x":"선적화물을 싣거나 내릴 때 화물의 개수를 계산하는 행위(항만하역사업으로)","o":"검수에 해당한다. 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"x":"선적화물 및 선박에 관련된 증명·조사·감정을 하는 행위(항만하역사업으로)","o":"감정에 해당한다. 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"x":"선적화물의 용적 또는 중량을 계산·증명하는 행위(항만하역사업으로)","o":"검량에 해당한다. 항만하역사업이 아니다.","src":"항만운송사업법 제2조 / 기출 2022-38"},{"x":"오픈탑 컨테이너는 경량화물 수송에 적합하다(2026-27 ㄷ).","o":"경량화물용으로 보는 설명은 오답이다.","src":"기출 2026-27 / 보충(추정)"},{"x":"탱크 컨테이너: 지붕 맨홀로 넣고 밑면을 호퍼형으로 만들어 배출(2026-27 ㄹ).","o":"그 설명은 벌크 컨테이너이다. 탱크 컨테이너는 액체용이다.","src":"기출 2026-27 / 보충(추정)"}]},"#17":{"묶음":[{"머리":"ULS의 의의·효과","줄":[{"t":"유닛로드시스템(ULS): 화물을 파렛트나 컨테이너 1개분으로 일정 중량·용적으로 단위화해 이 단위를 유지하며 운송·보관·하역하는 방식.","src":"기출 2021-37, 2022-36, 2024-33"},{"t":"선결과제: 운송 표준화, 장비 표준화, 하역 기계화.","src":"기출 2021-37, 2022-34"},{"t":"효과: 하역 기계화 촉진, 하역능력 향상으로 운송수단 회전율 상승, 보관효율 향상, 재고파악 용이, 파손·분실 감소, 포장 간소화와 포장비 절감, 인건비 절감.","src":"기출 2021-37, 2022-36, 2023-39, 2024-33"},{"t":"운반활성지수가 높아진다(감소가 아니다).","src":"기출 2024-37"},{"t":"단점: 하역기기 등에 고정투자비용이 들고 대규모 자본투자가 필요하다. 빈 파렛트·컨테이너 회수가 원활하지 않으면 운송·하역이 지연된다.","src":"기출 2023-39, 2024-33"},{"t":"일관파렛트화의 경제적 효과: 포장 간소화로 포장비 절감, 작업능률 향상, 화물 파손 감소, 운임·부대비용 절감, 화물 도난 감소, 물품검수 용이. 제품의 과잉생산 방지는 효과가 아니다.","src":"기출 2022-33, 2024-37"},{"t":"물류모듈화에서 파렛트화된 화물과 정합성을 맞출 대상: 랙, 파렛트 트럭, 컨테이너, 운반승강기. 해상용 갠트리 크레인은 해당하지 않는다.","src":"기출 2024-34"},{"t":"파렛트 풀 시스템 효과: 물류합리화·물류비 절감, 비수기 불필요한 파렛트 비용 절감, 파렛트 규격 표준화 필요, 지역적·계절적 수요 변동 대응. 회수관리를 일원화할 수 있다.","src":"기출 2021-32"}]},{"머리":"파렛트 표준규격","줄":[{"t":"한국 1,100×1,100mm, 일본 1,100×1,100mm, 영국 800×1,200mm(출제 정답), 미국 1,219×1,016mm.","src":"기출 2022-32"}]},{"머리":"파렛트 적재방식","줄":[{"t":"블록쌓기: 각 단의 모양과 방향을 모두 같게 일렬로 쌓는다. 작업은 쉽지만 무너질 위험이 있다.","src":"기출 2021-30, 2023-36"},{"t":"교호열쌓기: 같은 단 안에서는 같은 방향으로 나란히 놓고, 단마다 방향을 직각(90도)으로 바꾸거나 교대로 겹쳐 쌓는다.","src":"기출 2021-30"},{"t":"벽돌쌓기: 벽돌을 쌓듯이 가로·세로를 조합해 1단을 쌓고, 홀수층과 짝수층을 180도 회전시켜 쌓는다.","src":"기출 2023-36"},{"t":"핀휠(Pinwheel)쌓기: 중앙에 공간을 두고 풍차형으로 쌓는다.","src":"기출 2023-36"},{"t":"스플릿(Split)쌓기도 적재방식이다.","src":"기출 2021-30"}]},{"머리":"파렛트 종류 전체","줄":[{"t":"롤 파렛트(Roll Pallet): 바닥면에 바퀴가 달려 밀어서 움직인다.","src":"기출 2023-40, 2024-32, 2026-32"},{"t":"시트 파렛트(Sheet Pallet): 푸시풀(push-pull) 장치를 부착한 장비로 하역하는 시트 모양 1회용 파렛트.","src":"기출 2024-32, 2026-32"},{"t":"사일로 파렛트(Silo Pallet): 분말체의 보관·운송에 쓴다. 밀폐 커버와 하부 개폐장치가 있다.","src":"기출 2026-32, 2025-33"},{"t":"탱크 파렛트(Tank Pallet): 액체 취급에 쓴다. 밀폐 커버와 개폐 장치가 있다.","src":"기출 2025-33 / 보충"},{"t":"기둥(Post) 파렛트: 상단에 기둥을 설치해 기둥을 접거나 연결해 쓴다.","src":"기출 2026-32"},{"t":"스키드 파렛트: 핸드 리프트 등으로 하역하는 파렛트.","src":"기출 2025-33 / 보충(추정)"},{"t":"롤박스 파렛트: 상부가 박스이고 받침대 밑면에 바퀴가 달려 배송용으로 많이 쓴다.","src":"기출 2025-33"},{"t":"항공 파렛트: 화물 탑재 후 항공기 화물적재공간을 고려해 망(net)이나 띠(strap)로 묶는다.","src":"기출 2024-32"},{"t":"항공 단위탑재용기(ULD): 지상조업시간 단축으로 항공기 가동률 향상, 악천후·도난·파손 방지, 파렛트류·컨테이너류로 구분, IATA 검증을 거친 것도 있다. 모든 기종에 호환되지 않는다.","src":"기출 2025-37"}]},{"머리":"파렛트 풀 시스템 운영방식 전체","줄":[{"t":"교환(즉시교환)방식: 같은 수량의 파렛트를 동시에 교환한다. 동일 규격 파렛트를 미리 보유해야 하고 규격 통일이 선행되어야 한다. 유럽 국영철도역의 파렛트 적재 운송이 예다.","src":"기출 2021-35, 2022-35, 2024-35, 2026-34"},{"t":"교환방식은 동일 규격의 예비 파렛트 확보를 위한 추가비용이 발생한다.","src":"기출 2023-37"},{"t":"대차결제방식: 현장에서 즉시 교환하지 않고 일정 시간 내에 같은 수량의 파렛트를 반환한다.","src":"기출 2021-35"},{"t":"리스·렌탈방식: 개별 기업이 파렛트를 보유하지 않고 파렛트 풀 회사에서 일정 기간 임대한다. 이용자가 교환용 동일 수량을 준비할 필요가 없다. 운영 파렛트 수를 최소화하고 품질유지·보수가 쉽고 수급파동에 탄력적이다.","src":"기출 2021-35, 2022-35, 2023-37, 2025-32, 2026-34"},{"t":"교환·리스병용방식: 교환방식의 단점을 보완하려고 개발됐다.","src":"기출 2023-37, 2026-34 / 보충"}]}],"함정":[{"x":"파렛트 회수관리의 일원화에 어려움이 있다.","o":"파렛트 풀 시스템: 파렛트 회수관리를 일원화할 수 있다.","src":"기출 2021-32 / 기출 2021-32"},{"x":"파렛트는 시랜드사가 최초로 개발한 단위적재기기이다.","o":"시랜드사가 최초로 개발한 단위적재기기는 컨테이너이다.","src":"기출 2021-37 / 보충"},{"x":"화물을 파렛트나 컨테이너를 이용하여 벌크선박으로 운송한다.","o":"유닛로드시스템은 파렛트나 컨테이너로 단위화한 화물을 기계로 취급하는 방식이다. 벌크선박 운송과는 거리가 멀다.","src":"기출 2022-36 / 기출 2022-36"},{"x":"블록쌓기는 맨 아래에서 상단까지 일렬로 쌓는 방법으로 작업효율성이 높고 무 너질 염려가 없어 안정성이 높다.","o":"블록쌓기는 맨 아래에서 맨 위까지 같은 모양·방향으로 쌓아 작업은 쉽지만 무너질 위험이 있어 안정성이 낮다.","src":"기출 2023-36 / 기출 2021-30 / 보충"},{"x":"교호열쌓기는 짝수층과 홀수층을 180도 회전시켜 쌓는 방식으로 화물의 규격이 일정하지 않아도 적용이 가능한 방식이다.","o":"짝수층과 홀수층을 180도 회전시켜 쌓는 것은 벽돌쌓기이다. 교호열쌓기는 단별로 방향을 직각(90도)으로 바꾼다.","src":"기출 2023-36 / 기출 2021-30, 2023-36"},{"x":"핀휠(Pinwheel)쌓기는 비규격화물이나 정방형 파렛트가 아닌 경우에 이용하는 방식으로 다양한 화물의 적재에 이용된다.","o":"핀휠쌓기는 중앙에 공간을 두고 풍차형으로 쌓는다.","src":"기출 2023-36 / 기출 2023-36"},{"x":"스플릿(Split)쌓기는 중앙에 공간을 두고 풍차형으로 쌓는 방식으로 적재효율이 높고 안정적인 적재방식이다.","o":"중앙에 공간을 두고 풍차형으로 쌓는 방식은 핀휠쌓기이다.","src":"기출 2023-36 / 기출 2023-36"},{"x":"하역기기 등에 관한 고정투자비용이 발생하지 않기 때문에 대규모 자본투자가 필요 없다.","o":"유닛로드시스템은 하역기기 등에 고정투자비용이 들고 대규모 자본투자가 필요하다.","src":"기출 2023-39 / 기출 2023-39"},{"x":"시트 파렛트(Sheet Pallet)는 핸드리프트 등으로 움직일 수 있도록 만들어진 상자형 파렛트이다.","o":"시트 파렛트: 푸시풀 장치를 단 장비로 하역하는 얇은 판 모양의 1회용 파렛트이다.","src":"기출 2023-40 / 기출 2024-32, 2026-32"},{"x":"스키드 파렛트(Skid Pallet)는 상부구조물이 적어도 3면의 수직측판을 가진 상자형 파렛트이다.","o":"상부구조물에 적어도 3면의 수직측판을 가진 상자형 파렛트는 박스 파렛트이다.","src":"기출 2023-40 / 보충"},{"x":"사일로 파렛트(Silo Pallet)는 파렛트 상단에 기둥이 설치된 형태로 기둥을 접거나 연결하는 방식으로 사용한다.","o":"파렛트 상단에 기둥을 설치해 접거나 연결해 쓰는 것은 기둥(포스트) 파렛트이다. 사일로 파렛트는 분말체용이다.","src":"기출 2023-40 / 기출 2026-32"},{"x":"탱크 파렛트는(Tank Pallet)는 주로 분말체의 보관과 운송에 이용하는 1회용 파렛트이다.","o":"탱크 파렛트는 액체용이다. 분말체의 보관·운송용은 사일로 파렛트이다.","src":"기출 2023-40 / 기출 2026-32, 2025-33"},{"x":"사일로(silo) 파렛트는 액체를 담는 용도로 사용되며 밀폐를 위한 뚜껑이 있다.","o":"사일로 파렛트는 분말체용이다. 액체용은 탱크 파렛트이다.","src":"기출 2024-32 / 기출 2026-32, 2025-33"},{"x":"유닛로드시스템으로 운송의 편의성이 떨어졌고, 트럭 회전율 또한 감소하였다.","o":"유닛로드시스템으로 운송 편의성이 좋아지고 트럭 회전율이 증가했다.","src":"기출 2024-33 / 기출 2021-37, 2022-36"},{"x":"1회용 파렛트로 Push-Pull 장치를 부착한 지게차로 취급된다.","o":"푸시풀 장치 지게차로 취급하는 1회용 파렛트는 시트 파렛트이다.","src":"기출 2025-33 / 기출 2024-32, 2026-32"},{"x":"주로 액체화물 취급 시 사용되고 밀폐용 커버를 가지며 상부 또는 하부에 개폐 장치가 있다.","o":"액체화물용이며 밀폐 커버와 개폐 장치가 있는 파렛트는 탱크 파렛트이다.","src":"기출 2025-33 / 기출 2026-32 / 보충"},{"x":"주로 분말화물 취급 시 사용되고 밀폐용 커버를 가지며 하부에 개폐장치가 있다.","o":"분말화물용이며 밀폐 커버와 하부 개폐장치가 있는 파렛트는 사일로 파렛트이다.","src":"기출 2025-33 / 기출 2026-32 / 보충"},{"x":"핸드 리프트로 하역할 수 있도록 만들어진 단면형 및 양면형 파렛트이다.","o":"핸드 리프트로 하역할 수 있게 만든 단면형·양면형 파렛트는 스키드/플랫 계열의 설명이다. 롤박스 파렛트는 박스 모양에 바퀴가 달린다.","src":"기출 2025-33 / 보충(추정)"},{"x":"항공기의 모든 기종에 호환사용이 가능하여 사용회전률을 증가시킬 수 있다.","o":"항공 파렛트·컨테이너는 기종마다 규격이 달라 모든 기종에 호환되지 않는다.","src":"기출 2025-37 / 기출 2026-36"},{"x":"블록쌓기는 무너질 염려가 없어 안정성이 높다.","o":"무너질 염려가 있어 안정성이 낮다.","src":"기출 2023-36 / 보충"},{"x":"일관파렛트화의 효과: 제품의 과잉생산 방지","o":"효과가 아니다.","src":"기출 2022-33"},{"x":"일관파렛트화 장점: 운반활성지수 감소","o":"운반활성지수가 높아진다.","src":"기출 2024-37"},{"x":"해상용 갠트리 크레인은 파렛트화된 화물과 정합성을 고려해야 한다(2024-34).","o":"정합성을 고려할 필요가 없는 장비이다.","src":"기출 2024-34"},{"x":"대차결제방식: 운송업체가 화물을 인도하는 시점에 동일 수의 파렛트를 즉시 인수(2023-37 ㄷ)","o":"그 설명은 즉시교환방식이다.","src":"기출 2023-37, 2026-34"},{"x":"교환·리스병용방식은 대차결제방식의 단점을 보완하기 위해 개발(2023-37 ㄹ, 2026-34 ㄷ)","o":"교환방식의 단점을 보완하기 위한 방식이다.","src":"기출 2023-37, 2026-34 / 보충"},{"x":"한국 파렛트 표준규격은 1,100×1,200mm이다(2022-32 선지 조합 오류).","o":"한국 1,100×1,100mm, 일본 1,100×1,100mm, 영국 800×1,200mm, 미국 1,219×1,016mm.","src":"기출 2022-32"}]},"#18":{"묶음":[{"머리":"포장의 의의·기능·분류","줄":[{"t":"포장은 소비자의 관심을 유발하는 판매물류의 시작이며 물품의 가치를 높이거나 보호한다.","src":"기출 2023-33"},{"t":"포장 기능: 보호성, 표시성, 취급의 편리성, 판매촉진성. 상품 수요 예측의 정확성은 기능이 아니다.","src":"기출 2024-40"},{"t":"기능에 따라 공업포장과 상업포장으로 나눈다. 상업포장은 물품 개개의 단위포장으로 판매촉진이 목적이다.","src":"기출 2023-33 / 보충"},{"t":"겉포장: 화물 외부의 포장.","src":"기출 2023-33"}]},{"머리":"포장합리화 원칙","줄":[{"t":"대량화·대형화의 원칙: 포장의 대형화·대량화로 물류비를 절감한다.","src":"기출 2025-39, 2026-39"},{"t":"집중화·집약화의 원칙: 물량을 집중·집약해 물류비를 절감한다.","src":"기출 2021-26, 2025-39"},{"t":"사양변경의 원칙: 사양변경으로 물류비를 절감한다.","src":"기출 2025-39"},{"t":"재질변경의 원칙: 내용품 보호에 지장이 없는 범위에서 재질을 바꾼다.","src":"기출 2021-26, 2025-39, 2026-39"},{"t":"규격화·표준화의 원칙, 시스템화·단위화의 원칙.","src":"기출 2021-26, 2026-39"},{"t":"과잉포장을 배제하되 화물 보호를 심미성보다 우선한다.","src":"기출 2025-39 / 보충"},{"t":"통로대면의 원칙, 위치표시의 원칙은 보관 원칙이며 포장 원칙이 아니다.","src":"기출 2021-26, 2026-39"}]},{"머리":"주요 포장기법·결속","줄":[{"t":"방청 포장: 금속의 부식을 방지한다. 방수·방습·진공·완충 포장은 다른 목적이다.","src":"기출 2022-39"},{"t":"밴드결속: 플라스틱·나일론·금속 재질 밴드를 쓴다.","src":"기출 2022-40"},{"t":"꺽쇠 물림쇠: 주로 칸막이 상자 등에서 상자가 고정되게 한다.","src":"기출 2022-40"},{"t":"테이핑: 용기의 견고성을 유지하려고 접착테이프를 쓴다.","src":"기출 2022-40"},{"t":"대형 골판지 상자: 작은 부품 등을 꾸러미로 묶지 않고 담을 때 쓴다.","src":"기출 2022-40"},{"t":"슈링크(수축) 포장: 열수축성 플라스틱 필름을 씌우고 터널을 통과시켜 가열·수축시킨다.","src":"기출 2022-40 / 보충"}]},{"머리":"화인(Shipping Mark)","줄":[{"t":"화인은 기본화인, 정보화인, 취급주의 화인으로 구성되며 포장화물 외장에 표시한다.","src":"기출 2023-35"},{"t":"주화인(Main Mark): 타 화물과 식별을 쉽게 하는 기호. 수입업자 화인이며 일반적으로 도형 속에 머리글자를 넣는다.","src":"기출 2021-28, 2023-35, 2025-38"},{"t":"부화인(Counter Mark): 대조번호 화인. 생산자 또는 공급자의 약호를 붙여야 할 때 표기한다.","src":"기출 2023-35, 2025-38"},{"t":"항구표시(Port Mark): 선적과 양하작업이 쉽도록 도착항을 표시한다.","src":"기출 2021-28"},{"t":"품질 표시(Quality Mark): 내용물품의 품질·등급을 표시한다.","src":"기출 2023-35"},{"t":"취급주의 표시(Care Mark): 화물의 취급·운송·적재요령을 나타내는 주의표시.","src":"기출 2023-35, 2025-38"},{"t":"포장번호(Case Number)는 포장 순서·개수를 나타내는 번호 표시. 생산자 약호 표시가 아니다.","src":"기출 2021-28 / 보충(추정)"},{"t":"원산지표시(Origin Mark)는 물품의 생산국(원산지)을 표시한다. 원자재까지 모두 표시하는 것이 아니다.","src":"기출 2021-28 / 보충(추정)"},{"t":"화인에 표시할 수 있는 것: 원산지, 취급주의, 목적지, 품질, 중량 전부.","src":"기출 2026-40"}]},{"머리":"화인 표시방법","줄":[{"t":"스텐실(Stencil): 기름기가 많은 종이나 셀룰로이드판 등 시트에 문자를 파 두었다가 붓이나 스프레이로 칠한다.","src":"기출 2023-34, 2025-38"},{"t":"라벨링(Labeling): 종이·직포에 미리 인쇄해 두었다가 일정한 위치에 붙인다.","src":"기출 2023-34"},{"t":"태그(Tag): 종이·플라스틱판 등에 표시 내용을 기재한 뒤 철사나 끈으로 맨다. 의류·잡화류에 쓴다.","src":"기출 2023-34, 2025-38"}]}],"함정":[{"x":"슬리브 - 열수축성 플라스틱 필름을 화물에 씌우고 터널을 통과시킬 때 가열하 여 필름을 수축시키는 방법이다.","o":"열수축성 필름을 씌우고 터널에서 가열·수축시키는 방법은 슈링크(수축) 포장이다.","src":"기출 2022-40 / 보충"},{"x":"공업포장은 물품 개개의 단위포장으로 판매촉진이 주목적이다.","o":"물품 개개의 단위포장으로 판매촉진이 주목적인 포장은 상업포장이다. 공업포장은 수송·보관 중 물품 보호가 목적이다.","src":"기출 2023-33 / 보충"},{"x":"부화인 표시(Counter Mark)는 유통업자나 수입 대행사의 약호를 표시하는 기호 이다.","o":"부화인(Counter Mark): 생산자 또는 공급자의 약호를 표시한다.","src":"기출 2023-35 / 기출 2025-38"},{"x":"레이블링(Labeling) 방법: 종이, 알루미늄 등의 판에 표시내용을 기재한 다음 철사나 끈 등으로 적절히 매는 방법이다.","o":"종이·알루미늄 판에 기재해 철사나 끈으로 매는 방법은 태그(Tag)이다. 레이블링은 미리 인쇄한 종이·직포를 붙인다.","src":"기출 2025-38 / 기출 2023-34"},{"x":"심미성우선의 원칙: 과잉포장 배제를 통해 심미성을 화물보호보다 우선한다.","o":"포장합리화는 과잉포장을 배제하되 화물 보호를 우선한다. 심미성이 화물 보호보다 우선하지 않는다.","src":"기출 2025-39 / 보충"},{"x":"상품 수요 예측의 정확성(포장의 기능으로)","o":"포장의 기능이 아니다.","src":"기출 2024-40"},{"x":"통로대면의 원칙(포장의 원칙으로)","o":"보관의 원칙이다.","src":"기출 2021-26"},{"x":"위치표시의 원칙(포장합리화의 원칙으로)","o":"보관의 원칙이다.","src":"기출 2026-39"},{"x":"포장번호(Case Number): 주화인만으로 식별이 어려울 때 생산자 또는 공급자 약자를 보조 표시(2021-28 ㄴ)","o":"그 설명은 부화인이다. 포장번호는 포장 번호를 표시한다.","src":"기출 2021-28 / 보충(추정)"},{"x":"원산지표시: 당해 물품의 원자재까지 모두 원산지를 표시(2021-28 ㄹ)","o":"물품의 원산지를 표시하는 것이다. 원자재 원산지까지 표시하지 않는다.","src":"기출 2021-28 / 보충(추정)"},{"x":"스티커(Sticker)는 주물을 주입할 때 미리 화인을 해두는 방법(2023-34 ㄱ)","o":"출제 오답(바른 설명 미확인)","src":"기출 2023-34"},{"x":"스텐실(Stencil)은 고무인이나 프레스기 등으로 찍는 방법(2023-34 ㄴ)","o":"스텐실은 파 놓은 시트 위에 붓·스프레이로 칠하는 방법이다.","src":"기출 2023-34, 2025-38"}]}};
